-- 032_seed_press_releases.sql
-- Seed all 83 press releases from the previous Webflow site so
-- /press-releases/{slug} URLs continue to resolve after the DNS cutover.
--
-- Idempotent: deletes any prior press_releases rows from any Webflow-source
-- snapshot (some early local DBs labeled source as "MyEntertainment", later
-- snapshots as "myentertainment.tv") and re-seeds the canonical 83 rows.
-- The 2 hand-written editorial pages (film-commission-crew-directories,
-- myentertainment-careers-assignment-desk) live as static page.tsx files,
-- NOT as DB rows, so this DELETE never touches them.
--
-- Postgres conversion: strftime('%s','now') → EXTRACT(EPOCH FROM NOW())::INTEGER (seconds-epoch).
-- No other SQLite-specific syntax in the VALUES rows.

-- Generated: 2026-05-12T18:01:21.811Z
-- Source: https://www.myentertainment.tv/sitemap.xml

DELETE FROM press_releases;

