INSERT INTO press_releases
  (id, headline, slug, excerpt, body, source, source_url, published_at, is_featured, created_at, updated_at)
VALUES
  ('a-baby-at-first-sight-australia-set-to-get-reality-show-pregnant-platonic', 'Australia Gets Reality Show Pregnant & Platonic', 'a-baby-at-first-sight-australia-set-to-get-reality-show-pregnant-platonic', 'It sounds like an April Fool''s joke but reality TV could be about to delve into uncharted territory in the Australian market. Sydney-based Eureka Productions have picked up the rights to Pregnant &…', '<p>It sounds like an April Fool''s joke but reality TV could be about to delve into uncharted territory in the Australian market. Sydney-based Eureka Productions have picked up the rights to Pregnant &amp; Platonic, a controversial show matching singles together in order to co-parent a baby - without marriage or sex.Originally created in Israel, <a target="_blank" href="http://tvtonight.com.au/2017/03/pregnant-platonic-next-for-australia.html">TV Tonight</a> reports that the show could become the latest in a long line of reality programs to thrive on our screens if the rights are bought by a broadcaster.Pregnant &amp; Platonic gives singles the choice between three prospective partners that have been hand selected for them by a group of experts.They then undergo a three-day ''parenting boot camp'' to determine whether their parenting styles and core values are compatible.If a partner is chosen, the show will follow the couple''s journey as they attempt to become a family and make the unorthodox arrangement work.The show''s founder, Assaf Gil, conceived the idea after co-parenting his first child last year. After securing the Australian rights, Eureka will now have to find a broadcaster to back the concept. And given the ratings success of recent reality shows, Pregnant &amp; Platonic may eventually make it on to our screens.</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/a-baby-at-first-sight-australia-set-to-get-reality-show-pregnant-platonic', 1490932800, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('breaking-borders-gathers-people-from-all-sides-of-a-conflict-for-a-real-conversation-at-the-dinner-table', '"Breaking Borders" Gathers People In Conflict for a Real Conversation', 'breaking-borders-gathers-people-from-all-sides-of-a-conflict-for-a-real-conversation-at-the-dinner-table', 'Can breaking bread actually make a difference when it comes to Breaking Borders? In Travel Channel’s new original series, premiering Sunday, March 15 at 9:00 p.m. ET/PT, Peabody Award-winning journ…', '<p>Can breaking bread actually make a difference when it comes to Breaking Borders? In Travel Channel’s new original series, premiering Sunday, March 15 at 9:00 p.m. ET/PT, Peabody Award-winning journalist Mariana van Zeller and acclaimed chef Michael Voltaggio tackle that very question as they travel to conflict zones around the globe. Together, they have a unique and challenging goal: gather people from all sides of the conflict to a delicious meal and talk about the issues that divide them. A thoughtful and informative hour, Breaking Borders is a unique opportunity for those living in the region to share their challenges, concerns and possibilities of a future – through the eyes of the community members whose daily experiences continue to drive international headlines. The series is comprised of 13 one-hour episodes.In each episode, van Zeller and Voltaggio take viewers on a journey to meet residents affected by the unrest. They go into their homes and businesses, uncover their culinary cultures, likes and dislikes and learn how each respective cuisine helps define who they are. As van Zeller digs deeper into the issues, Voltaggio goes on a culinary adventure, collecting ideas and ingredients to create an unbelievable meal inspired by the people he has encountered along the way.“It’s amazing how people talk more freely around a dinner table. Food always unites, even where war divides,” says van Zeller. “What we found at the center of each of these conflicts are people with their own truths to tell. The series is a wild ride – rich with stories of war, food, tears, laughter, fear, bravery and survival.”“For each location, I arrived with just my bag of knives and a vague idea of some of the most traditional foods from the region,” says Voltaggio. “I started from scratch buying every ingredient on the ground and constructing my interpretation of the local cuisine. I put 100% of myself into cooking every meal. It was an honor to sit at the table and hear the stories.”In the premiere episode, van Zeller and Voltaggio travel to Israel and Palestine to take a closer look at the mother of all conflicts and learn how it has shaped these nations. They meet people affected by the unrest in Jerusalem and the West Bank, and explore some of the holiest sites on Earth. Immersing themselves in the culture, they experience Jerusalem and the West Bank in a way that goes beyond the conflict, showcasing what makes this biblical region a truly unique place to visit.They prepare for their big event – the dinner – with excitement and definite trepidation. Van Zeller introduces the dinner guests representing the opposing sides of the conflict: Yaakov and Naama Berg, Jewish settlers; Yoram Cohen and his family, Jewish settlers; Munther Fhami, a Palestinian book store owner; Sameer, their Palestinian “fixer/guide;” and Israeli Yariv Oppenheimer, General Director of “Peace Now,” a pro two-state solution organization. With the group seated around the table, Voltaggio presents the first kosher dinner he has ever prepared which combines the local spices, flavors and traditions of the region. As they enjoy the meal, the guests discuss their personal views, hopes and fears. Though there is some tension, all participants are open to hearing each other’s viewpoints, bringing insight and a greater understanding to the ongoing conversation. In the end, Voltaggio and van Zeller orchestrate a successful meal, with Israeli settlers and Palestinians coming together to candidly talk about the age-old problems and controversies that still surround them today.Van Zeller and Voltaggio continue their travels into various conflict zones throughout the season to reveal the personal stories behind the story: they head to Belfast to understand what happened during the 30-year war in Northern Ireland between Catholic Republicans and Protestant Nationalists; travel to Cairo to explore the chaotic reality of the country post-Arab Spring; investigate the island and capital city of Cyprus divided by age-old enemies; crisscross Beirut and Tripoli to explore a country in paradox; and journey to Sarajevo to grasp how three distinct ethnic groups – Serbs, Croats and Bosniaks – co-exist in one city after civil war and ethnic cleansing. Additional locations featured in the series include Arizona/Mexico, Cambodia, Cuba, Kashmir, Myanmar/Burma, Rwanda and Sri Lanka.</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/breaking-borders-gathers-people-from-all-sides-of-a-conflict-for-a-real-conversation-at-the-dinner-table', 1425531600, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('coming-soon-sin-city-justice', 'Coming Soon: "Sin City Justice"', 'coming-soon-sin-city-justice', 'In this week’s round-up, new non-fiction docuseries are slated to debut across Investigation Discovery, Complex Networks, HLN and TV One.Global lifestyle brand and media company Complex Networks wi…', '<p>In this week’s round-up, new non-fiction docuseries are slated to debut across Investigation Discovery, Complex Networks, HLN and TV One.Global lifestyle brand and media company Complex Networks will accompany a young, self-taught survivalist on a variety of adventures in Going Cambo!Produced by Rated Red, the docuseries features Cameron “Cambo” Bowling as he takes guests on a 48-hour adventure through the wilderness of Alabama. Each week, three episodes ranging in length from six to nine minutes will see visitors dropped into remote locations in the backwoods of Alabama and are taught, by Cambo, to live and survive off the wild terrain. Going Cambo! premieres May 30 on streaming service go90 and are scheduled for release on Tuesdays, Thursdays and Saturdays.Elsewhere, American cable net HLN will debut Nutopia’s true crime series Beyond Reasonable Doubt on June 2 at 9 p.m. ET/PT.The 6 x 60 docuseries will take viewers inside the world of forensic investigation through high-profile criminal cases that have unraveled over the past century and were ultimately solved by advances in forensic science or technology. Among the infamous cases explored in the series, which features the lead detective of each case, are the Green River Killer and 1996 Atlanta bombings.Meanwhile, Urban One-owned cable net TV One will add to its true crime line-up with Jupiter Entertainment’s #Murder.The series will look to explore deadly crimes with a connection to technology and social media, from the killer and victim meeting online, to the murderer posting incriminating details on Facebook, and law enforcement teams using social media to hunt down the perpetrator. TV One will broadcast #Murder on June 5 at 10 p.m. ET/PT.Finally, true crime channel Investigation Discovery will delve into the Las Vegas crime scene with MY Entertainment’s Sin City Justice (pictured).The vérité-shot series, formerly Las Vegas Law and bows June 8 at 10 p.m. ET/PT, provides exclusive access to Las Vegas district attorney Steve Wolfson and the Clark County District Attorney’s office as they pursue justice in their community.The series, which features surveillance footage and photography, will document the DA’s office as they assess each crime scene and interview victims and witnesses while also chasing a conviction in the courtroom. Sin City Justice will use surveillance footage, police interrogation video, and photography never-before-released to immerse viewers in the high stakes legal environment.</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/coming-soon-sin-city-justice', 1495684800, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('discovery-heads-to-brooklyn-with-billy', 'Discovery heads to Brooklyn with Billy', 'discovery-heads-to-brooklyn-with-billy', 'US factual giant Discovery has commissioned a new series fronted by the star of long-running Travel Channel series Baggage Battles for its global networks.Billy Buys Brooklyn is being produced by N…', '<p>US factual giant Discovery has commissioned a new series fronted by the star of long-running Travel Channel series Baggage Battles for its global networks.Billy Buys Brooklyn is being produced by New York-based indie MY Entertainment and will air on DMAX UK, Italy, Spain and Germany, and Discovery Channel US and Europe.The series follows Billy LeRoy on his latest venture, a new vintage, antiques and collectables store in Brooklyn, New York City.Simon Downing, senior VP and head of factual and sport at Discovery, and Victoria Noble, VP of original content for factual, ordered the series and the exec producer for Discovery is Jon Stephens.Executive producers for MY Entertainment are Michael Yudin, Joe Townley and John Yakovou.Baggage Battles premiered on Discovery-owned Travel Channel in 20212 and has aired for five seasons.</p><p>https://www.c21media.net/discovery-heads-to-brooklyn-with-billy/</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/discovery-heads-to-brooklyn-with-billy', 1603080000, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('discovery-orders-global-series-billy-buys-brooklyn-featuring-baggage-battles-star-billy-leroy', 'Discovery Orders Global Series ‘Billy Buys Brooklyn’ Featuring ‘Baggage Battles’ Star Billy Leroy', 'discovery-orders-global-series-billy-buys-brooklyn-featuring-baggage-battles-star-billy-leroy', 'Billy Leroy, the star of Travel Channel’s Baggage Battles , is to front a global series for Discovery in which he opens a vintage, antiques, and collectibles store in Brooklyn, New York. Billy Buys…', '<p>Billy Leroy, the star of Travel Channel’s<em> Baggage Battles</em>, is to front a global series for <a href="https://deadline.com/tag/discovery/">Discovery</a> in which he opens a vintage, antiques, and collectibles store in Brooklyn, New York.<a href="https://deadline.com/tag/billy-buys-brooklyn/"><em>Billy Buys Brooklyn</em></a> (working title) is produced by <a href="https://deadline.com/tag/my-entertainment/">MY Entertainment</a> and will stream on dplay, as well as play on linear channels including DMAX UK, Italy, Spain and Germany, and Discovery Channel US and Europe.The show follows Leroy as he opens Billy’s Antiques &amp; Props and uses his knowledge, curiosity, and network of contacts to seeks out the most unique items to make his new venture a success.Billy and his team never know who will come through the door and invites sellers to guess their items’ worth before revealing their estimates. Items featured include a Haro BMX Bike and a Victorian walking cane hiding a secret gun.<em>Billy Buys Brooklyn</em> was ordered by Discovery UK’s head of factual and sport Simon Downing and Victoria Noble, VP of original factual content, while the executive producer for Discovery is Jon Stephens. Executive producers for MY Entertainment are Michael Yudin, Joe Townley and John Yakovou.</p><p>https://deadline.com/2020/10/discovery-global-series-billy-buys-brooklyn-featuring-baggage-battles-billy-leroy-1234596304/</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/discovery-orders-global-series-billy-buys-brooklyn-featuring-baggage-battles-star-billy-leroy', 1603080000, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('district-attorney-steve-wolfson-staff-on-reality-tv-series-vegas-d-a', 'Las Vegas District Attorney Steve Wolfson Stars in New Reality-TV series', 'district-attorney-steve-wolfson-staff-on-reality-tv-series-vegas-d-a', 'Clark County District Attorney Steve Wolfson and his staff are under the glare of bright lights and cameras all week at the Regional Justice Center as crews shoot episodes of the new reality-TV ser…', '<p>Clark County District Attorney Steve Wolfson and his staff are under the glare of bright lights and cameras all week at the Regional Justice Center as crews shoot episodes of the new reality-TV series “Vegas D.A.”Local bestselling author and 2008 Libertarian Vice Presidential nominee Wayne Root created the new concept and is co-producing it under his Cool Hand Root TV production banner with Michael Yudin’s My Tupelo Entertainment, which produces “Ghost Adventures” on the Travel Channel.“The show is not only based on our great system, its justice system and the D.A.’s Office, but it also will have Las Vegas roots on the production end,” Wayne told me.Michael and Wayne’s collaborations include “King of Vegas,” which garnered more than 1 million viewers for Spike TV in 2006, and “Ghost Adventures,” starring Las Vegas’ Zak Bagans and now the No. 1 show in Travel Channel history.Wayne also is celebrating his latest book deal, “The Power of Relentless,” his 10th book but first business and personal development tome. Donald Trump and Wayne are the first two authors signed to Regnery Publishing’s new business book division.Wayne’s last two political books were national bestsellers with Regnery: “The Ultimate Obama Survival Guide” and “The Murder of the Middle Class.”Wayne tells me that “Relentless” is about the most important trait for success in career, business, relationships and life — being 110 percent committed, dedicated, unstoppable, goal obsessed and thus relentless.He teaches a three-part program of empowerment and a triad game plan for success over competition.Robin Leach has been a journalist for more than 50 years and has spent the past 15 years giving readers the inside scoop on Las Vegas, the world’s premier platinum playground.</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/district-attorney-steve-wolfson-staff-on-reality-tv-series-vegas-d-a', 1394596800, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('europe-adopts-gils-co-parenting-format', 'Europe Adopts Gil’s Co-Parenting Format', 'europe-adopts-gils-co-parenting-format', 'Media groups across Europe have optioned rights to Gil Formats’ Pregnant &amp; Platonic, which looks at the rising trend of co-parenting.The Israeli factual entertainment format, which was launched…', '<p>Media groups across Europe have optioned rights to Gil Formats’ Pregnant &amp; Platonic, which looks at the rising trend of co-parenting.The Israeli factual entertainment format, which was <a href="http://www.c21media.net/gil-conceives-co-parenting-format/">launched</a> at Mipcom in October, centres on women and men who are looking to have a child without being in a romantic relationship.It was inspired by the personal experience of Gil Formats CEO Assaf Gil, who had his first child last year with a co-parent.Finestripe Productions in the UK, Endemol Shine Germany, This Is Nice Group in Sweden and Bulldog TV in Spain have now optioned the rights to the format, which was co-developed wth US prodco My Entertainment.“Pregnant &amp; Platonic builds on Gil Formats’ repertoire of ground-breaking, insightful and innovative television. The format brings the unique personal context of those women and men who are looking to have a child without falling in love, through the growing phenomenon of co-parenting,” said Gil.“Securing option deals in four territories just shortly after the format’s official launch at Mipcom demonstrates strong demand for this new concept in factual entertainment storytelling.”Gil Formats is the development and distribution arm of Israel’s Gil Productions.</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/europe-adopts-gils-co-parenting-format', 1483678800, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('exclusive-joanna-zwickel-to-lead-my-entertainments-premium-content-division', 'Exclusive: Joanna Zwickel to lead MY Entertainment’s premium content division', 'exclusive-joanna-zwickel-to-lead-my-entertainments-premium-content-division', 'Michael Yudin‘s New York-headquartered indie MY Entertainment (MYE) has tapped former MRC Studios executive Joanna Zwickel to lead its newly formed premium content division as part of the company’s…', '<p>Michael Yudin‘s New York-headquartered indie MY Entertainment (MYE) has tapped former MRC Studios executive Joanna Zwickel to lead its newly formed premium content division as part of the company’s push to maximize the value of its intellectual property.Zwickel (pictured) will serve as head of development for the newly-minted One Foot Forward Entertainment, where she will have oversight of MYE’s move into premium content targeted at all major streaming services.She reports into MYE president Michael Yudin and Joe Townley, chief operating officer and executive producer.One Foot Forward will continue to produce non-scripted entertainment programs under the MY Entertainment brand as the studio focuses on the “booming” premium content marketplace.MY Entertainment, for its part, has managed to keep 10 non-scripted projects in production throughout the enduring COVID-19 pandemic.Zwickel joins MYE from MRC Studios, where she served as VP of television development. Before that, she held a number of senior roles at several top-performing companies, including serving as head of TV development at <em>The Hollywood Reporter </em>and <em>Billboard</em>; and manager of Blumhouse Productions’ television division.The experienced development executive and producer’s recent projects include Hulu’s critically acclaimed documentary <em>Fyre Fraud</em>, Sundance’s true crime series <em>No One Saw a Thing</em>, HBO’s <em>Liberty: Mother of Exiles</em> and Peacock’s scripted series <em>Angelyne</em>, starring Emmy Rossum.“MY Entertainment has evolved over the years from the days of producing for only three national networks, through some of the first-ever branded entertainment successes, navigating 500 cable channels and now an infinite number of platforms and devices to consume content,” Yudin said in a statement. “We have always been able to successfully answer the call to supply quality ‘sticky’ content that has proven to be rating successes whatever the requirement. We are therefore thrilled to have Joanna lead us into the world of streamers, where we believe we will continue in this same tradition.”“Michael and his team have maintained a thriving business model, while allowing room to change and grow as the industry continues to pivot towards streaming,” Zwickel added. “I’m thrilled to join Michael’s team and excited about launching a premium content division to produce fresh and original programming with top-tier talent.”</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/exclusive-joanna-zwickel-to-lead-my-entertainments-premium-content-division', 1601352000, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('exclusive-my-entertainment-teams-up-with-nbas-tyson-chandler', 'MY Entertainment Teams Up with Style Icon Tyson Chandler', 'exclusive-my-entertainment-teams-up-with-nbas-tyson-chandler', 'New York-based independent production company MY Entertainment is teaming up with NBA All-Star and style icon Tyson Chandler (pictured) to develop a new reality television series taking viewers beh…', '<p>New York-based independent production company MY Entertainment is teaming up with NBA All-Star and style icon Tyson Chandler (pictured) to develop a new reality television series taking viewers behind-the-scenes into the exciting world of fashion in sports.Chandler, whose style off the court has landed him in the pages of top fashion magazines and front row at designer fashion shows, will serve as an executive producer and make appearances on the show, which will focus on his design stylist and fashion consultant, Browne Andrews.In the series, Andrews will take viewers into his inner circle of top stylists to provide an up-close and inside look at the high pressures of keeping their NBA clients in the fashion spotlight.“An NBA World Champion and consistently named one of the league’s most fashionable players, Tyson Chandler is the perfect partner for this show,” said <a target="_blank" href="http://xchange.realscreen.com/realxchange/main/profile/public/15217">Michael Yudin</a>, president of MY Entertainment, in a statement. “The entrance and exit to games has become a virtual runway for NBA stars. We are thrilled to work with Tyson and influential stylist and fashion director, Browne Andrews to bring people into the exciting, fast paced and high-pressure world of top stylists trying to deliver a fashion win for their superstar clients.”<a target="_blank" href="http://xchange.realscreen.com/realxchange/main/profile/public/13653">Joe Townley</a>, COO at MY Entertainment, and <a target="_blank" href="http://xchange.realscreen.com/realxchange/main/profile/public/14069">David Auerbach</a>, SVP at MY Entertainment, will serve as executive producers for the show along with Chandler.</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/exclusive-my-entertainment-teams-up-with-nbas-tyson-chandler', 1491796800, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('ghost-adventures', 'Ghost Adventures', 'ghost-adventures', 'GHOST ADVENTURES The stars of the award winning documentary feature, Ghost Adventures, hit the road searching for the most evil, sinister and haunted locations in the US to investigate, and put the…', '<figure><div><img src="https://cdn.prod.website-files.com/636ec04871bc7356ad940743/636ec0ef71bc7306e1940de3_travelchannel-1.png" alt="Ghost Adventures"></div></figure><h4>GHOST ADVENTURES</h4><p>The stars of the award winning documentary feature, Ghost Adventures, hit the road searching for the most evil, sinister and haunted locations in the US to investigate, and put themselves face to face with the evil spirits who have documented reports of injuries to the living. During the investigations, they use their trademark “raw” technique while inside these haunted locations. Starring Zak Bagans, Aaron Goodwin, Billy Tolley and Jay Wasley.</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/ghost-adventures', 1547787600, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('ghost-adventures-horror-at-joe-exotics-zoo', 'Ghost Adventures: Horror at Joe Exotic’s Zoo', 'ghost-adventures-horror-at-joe-exotics-zoo', 'Ghost Adventures is taking on the dark and twisted world of Joe Exotic''s former zoo. The Travel Channel series headed to the site of the Tiger King documentary to investigate the spirits that may h…', '<p>Ghost Adventures is taking on the dark and twisted world of Joe Exotic''s former zoo. The Travel Channel series headed to the site of the Tiger King documentary to investigate the spirits that may haunt the property.Star Zak Bagans and his crew of paranormal investigators headed to what was once the Greater Wynnewood Exotic Animal Park, and they claim to have experienced some truly striking supernatural encounters.Bagans spoke with ET''s Kevin Frazier about the special episode of Ghost Adventures, and admitted to getting particularly emotional about this investigation."I 100% believe that Travis Maldonado''s spirit was there," Bagans shared. "We captured a figure on a device that we use, OK... and this figure was pointing at something in a closet. That directed us to go look in that closet. And when we looked on the top shelf we found an item that belonged to Travis."As seen in the acclaimed Netflix documentary, Maldonado was an employee at the zoo, and also one of Exotic''s multiple husbands. In one of the most horrifying and disturbing moments in the documentary, Maldonado accidentally killed himself while messing around with a handgun he didn''t know was loaded."He''s trying to send messages out," Bagans claimed, referring to Maldonado''s spirit. "Travis was not ready to leave this earth. He was not ready. This was an accident, and he still cares about a lot of the people that were there, and he wants to speak. He wants to convey messages.""It really is a tragedy that occurred, already in a chaotic storm of energy from the events that you and everybody that has watched Tiger King know of," Bagans shared. "And let me tell you, going there, it was the same thing.""I believe that there is an underlying residual energy attached to this place, particularly in this area called the Back 40," he explained, referring to an open area of the zoo where the remains of several tigers were buried during the time to zoo was open. "I''ve been investigating the most haunted forest in the world... and when I went into this Back 40 area, that scared me more than that damn forest."Bagans also said that he would "100%" love to conduct a Ghost Adventures investigation into the property owned by fellow Tiger King subject, and Exotic''s nemesis, Carole Baskin."Carole Baskin, if you are watching this, you are going to see our investigation of Joe Exotic''s zoo, and how we conducted that, so I ask you, please, let us come investigate your property," Bagans implored.</p><p>Ghost Adventures: Horror at Joe Exotic Zoo airs Thursday, Oct. 29 at 9 p.m. ET/PT on the Travel Channel.</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/ghost-adventures-horror-at-joe-exotics-zoo', 1604379600, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('ghost-adventures-live-to-air-from-zak-bagans-las-vegas-museum', '‘Ghost Adventures Live’ to air from Zak Bagans’ Las Vegas museum', 'ghost-adventures-live-to-air-from-zak-bagans-las-vegas-museum', 'Zak Bagans is posing for photos in front of the Dybbuk Box, the wine cabinet with a reputation as one of the world’s most haunted objects, when he starts to feel uncomfortable in its presence. Comi…', '<p>Zak Bagans is posing for photos in front of the Dybbuk Box, the wine cabinet with a reputation as one of the world’s most haunted objects, when he starts to feel uncomfortable in its presence. Coming from a man who could have earned a doctorate in heebie-jeebies, it’s the sort of admission that should trigger alarms throughout his Haunted Museum. Heck, anyone in the vicinity of the 11,000-square-foot Tudor revival built in 1938, at 600 E. Charleston Blvd., should receive a emergency alert.The bottom line: When the lead investigator of “Ghost Adventures” doesn’t like the energy in a room, you get out of that room as fast as you can — preferably without leaving a writer-shaped hole in the wall.<strong>‘More scared now’</strong>“Yes, I still do get scared. I actually am more scared now than I was when I first started, because I’ve developed such a hypersensitivity to this stuff now after all these experiences.”Bagans says this later, in one of the Haunted Museum’s 32 other rooms. The heavy door can’t quite block out the calliope music that echoes from another room. Funhouse-style statues and dolls that could put Annabelle to shame threaten to overtake the small space. It’s as though the room were designed to be the last one that Mike and Frank would wander into in the terrifying final episode of “American Pickers.”The Dybbuk Box is one of the featured attractions of “Ghost Adventures Live,” a four-hour Travel Channel special scheduled to broadcast from the museum at 5 p.m. Wednesday.According to a press release, “Bagans will attempt to open the Dybbuk Box, quite possibly evoking paranormal mayhem.”But Bagans isn’t so sure about that considering what happened the second — and, as of now, the last — time he touched it.<strong>From perfectly normal to paranormal</strong></p><p>Around 10:30 p.m. June 22, rapper Post Malone stopped by the Haunted Museum after his concert at the Park Theater.</p><p>“We’re just having fun, just a couple of buddies hanging out,” Bagans recalls. “Everything’s perfectly normal.”Or at least as normal as could be expected inside an attraction that’s arranged like a sort of <a target="_blank" href="http://www.hotels.vegas/Las-Vegas-Hotels/Planet-Hollywood-Resort-And-Casino">Planet Hollywood</a> of the Damned.The two decided to enter the room that houses the Dybbuk Box, but they ran back down the stairs as soon as they heard a little girl’s voice. They eventually went back and, for reasons he can’t explain, Bagans says he wanted to remove the box from its case. As soon as he touched the object, Post Malone put his hand on Bagans’ shoulder.“It was like somebody put, like, a Taser of fear onto me,” the 41-year-old Bagans explains. “I began crying. I began screaming. I began hyperventilating.”Security video from that moment plays on a loop in the antechamber of the Dybbuk Box room. The monitor hangs above the case displaying a costume that Matisyahu wore in “The Possession,” the 2012 horror movie that the box inspired.After that, the two lost track of time. A check of the health app on Bagans’ phone revealed they went up and down those stairs 84 times that night.</p><p>The next day, Post Malone sent Bagans a photo of a massive bruise that he didn’t remember receiving. In the ensuing weeks, the rapper’s jet had to make an emergency landing when two of its tires blew out, his Rolls-Royce was T-boned by a Kia, and gunmen broke into his former home looking for him.</p><p>“I don’t know if I’m going to open the Dybbuk Box,” Bagans admits. “We’re going to see what happens and what progresses.”</p><p><strong>Trying to ‘summon things’</strong>He does, however, promise that “Ghost Adventures Live” will include a “multiple-event investigation” involving his team, as well as electrical engineers, psychic mediums, an exorcist and Wendy Binks, aka Lady Snake, a “dark witch” from England.“In a mansion full of paranormal-charged artifacts, I wanna bring in people who are also charged,” Bagans says, “and bring in also some people that have the abilities to develop some really scientific-based equipment.”He’s also planning to re-create some of the dark rituals that were rumored to have taken place in the museum’s basement during the 1970s.“We’re gonna take things out of their cases. We’re gonna touch them. We’re gonna try to summon things. And we’re gonna just investigate what’s already here at the mansion.”<strong>Another live investigation</strong>“Ghost Adventures Live” is the franchise’s first special to air in real time since Oct. 30, 2009, when the Ghost Adventures Crew took part in a seven-hour live investigation of West Virginia’s Trans-Allegheny Lunatic Asylum.Bagans acknowledges that the Halloween event is a great way to celebrate the 10th anniversary of “Ghost Adventures” — the new season begins at 9 p.m. Saturday, Nov. 3 — as well as the museum’s first year in business.“The things that we’ve been experiencing in the last year — people, guests, things that I’ve experienced, my staff — it was a no-brainer to just do something here live,” he says. “There’s just so many different elements of what can be contributing to the hauntings here.”Even so, he’s no fan of live investigations.For starters, Bagans is never sure how he’ll react, and he isn’t thrilled with the idea of his unedited emotions being broadcast around the world. He happened to be facing away from the security camera that captured the incident with Post Malone, otherwise the memes would have been enough to break a man.“I’m not crazy about live, because when you do a proper paranormal investigation, it takes a lot of time, and you don’t know when things are going to happen. When we do an investigation on ‘Ghost Adventures,’ we could be there for 10 hours. So we’re showing you 20 minutes of the best parts.”Still, Bagans is pulling out all the stops to try to ensure excitement during the special.“I’m doing things to try to open those veils, to summon the spirits, and bringing in these people that I know have the abilities to do that. The best of the best.“So there’s very, very good chances that some very crazy things are going to happen.”<strong>Cheer on the crew</strong>Fans who want to be a part of “Ghost Adventures Live” can participate outside the Haunted Museum, 600 E. Charleston Blvd.Plan to arrive by 3 p.m. Wednesday to cheer on Zak Bagans and the Ghost Adventures Crew.</p><p>Filming of the crowd scenes is scheduled to end at 6 p.m.</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/ghost-adventures-live-to-air-from-zak-bagans-las-vegas-museum', 1540872000, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('ghost-adventures-locks-down-travel-channels-spook-filled-ghostober-event', 'GHOST ADVENTURES Locks Down Travel Channel''s Spook-Filled ''Ghostober'' Event', 'ghost-adventures-locks-down-travel-channels-spook-filled-ghostober-event', 'Creepy thrills await as Travel Channel hosts the ultimate Halloween event this "Ghostober" - a cauldron of spooky, creepy and terrifying programming that will take viewers on a fun, spine-tingling …', '<p>Creepy thrills await as Travel Channel hosts the ultimate Halloween event this "Ghostober" - a cauldron of spooky, creepy and terrifying programming that will take viewers on a fun, spine-tingling journey across America.The goosebumps begin Saturday, October 6 at 9 p.m. ET/PT with a four-part, four-week long "Ghost Adventures" miniseries that takes the paranormal investigative team - Zak Bagans, Aaron Goodwin, Billy Tolley and Jay Wasley - to the "Graveyard of the Pacific," a treacherous nautical region in the Pacific Northwest. New series, specials and episodes continue all month long, culminating on Halloween night with "Ghost Adventures Live" - a special four-hour live investigation inside Zak Bagans'' Las Vegas Haunted Museum. With special guests, creepy objects that contain haunted histories and fan involvement, it''s the ultimate Halloween treat.Additional premieres throughout the month include:· "Chris Jericho: Monster Hunt" (wt), a one-hour special following WWE world champion and entertainer Chris Jericho as he searches for legendary swamp creatures in Southern Louisiana.· "Scariest Night of My Life," retelling chilling stories from victims of paranormal mayhem.· "Most Terrifying Places in America," showcasing the nation''s most horrifying haunts.· "Haunted Live," a weekly live and interactive ghost hunting series where viewers can help guide the investigation."Anchored by our mega-hit ''Ghost Adventures,'' the entire month of October is a spooky and wild Halloween celebration with the most innovative creepy content and the biggest stars in the paranormal universe," said Jane Latman, general manager, Travel Channel. "Between our live investigations and spine-tingling new specials, ''Ghostober'' is not for the faint of heart. Watch only if you dare."Visit TravelChannel.com and follow Travel Channel''s Facebook, Twitter and Instagram pages where the "Ghostober" party continues all month long. Fans can check out exclusive content from their favorite series, including behind-the-scenes videos, photos and exciting giveaways. Join the conversation during live tweeting and real-time Q&amp;A sessions with show hosts on Facebook Live including Zak Bagans and the "Ghost Adventures" crew. Amping up the fun is an all-new digital series, "Friday Night with Gunnarolla," which follows Andrew "Gunnarolla" Gunadie as he embraces the frights and checks into spooky locations around the United States, and a new Facebook Live series that will follow James B. McDaniel, also known as Peppermint Fatty, as he recaps the week''s episodes and shares exclusive sneak peek videos from upcoming premieres, including "Ghost Adventures" and "Haunted Live.""GHOSTOBER" LINEUP:NEW SERIESSCARIEST NIGHT OF MY LIFEPremieres Sunday, September 9 at 10 p.m. ET/PT (continues through October)"Scariest Night of My Life" retells chilling, true stories of victims of paranormal mayhem. Each episode features three different stories of people who lived through life-changing and spine-chilling supernatural encounters that happened during the course of one terrifying night. With powerful recreations filled with twists and turns, viewers are in for an unforgettable paranormal ride. #ScariestNightofMyLifeHAUNTED LIVEPremieres Friday, September 14 at 10 p.m. ET/PT (continues through October)Viewers are invited to join the action in "Haunted Live," a live interactive paranormal investigation series featuring the Tennessee Wraith Chasers, a team of paranormal experts that relies on a unique combination of scientific method and spiritual faith to navigate investigations. Each week, the team members will reveal a new haunted location to the public and utilize their skills, technology and unique experiments to capture evidence of paranormal activity in a live and unfiltered paranormal investigation. Through an on-location live video stream, viewers can monitor all of the "Haunted Live" activity on Travel Channel''s Facebook Live platform and comment on any findings in real time, directing the team where to investigate next. Fans can follow Travel Channel''s social media pages for the secret location reveal each week, and visit Facebook to join a special pre-hunt Q&amp;A with the Tennessee Wraith Chasers. #HauntedLiveNEW SPECIALSMYSTERIES AT THE MUSEUM - "Special: Zodiac Killer"One-Hour SpecialPremieres Wednesday, October 3 at 9 p.m. ET/PTHistory enthusiast and adventurer Don Wildman investigates the most notorious unsolved crime in American history - the Zodiac murders. Diving headfirst into the case, Wildman meets with a retired inspector who worked the crimes, learns code-breaking from a Zodiac cryptographer, visits a DNA lab to understand how close authorities are to catching the killer and learns a new theory on who may be responsible. #MATMCHRIS JERICHO: MONSTER HUNT (wt)One-Hour SpecialPremieres Wednesday, October 10 at 10 p.m. ET/PTWWE champion and famed author, musician and podcaster Chris Jericho has had a lifelong fascination with the unexplained. Now, he is on a terrifying mission to uncover the truth behind the fearsome swamp creatures believed to inhabit the swamps of Southern Louisiana. Wading deep into bayou country, Jericho searches for evidence of a legendary creature known as Rougarou, and a Sasquatch-like beast that roams the Honey Island Swamp. Is there a connection between these monsters? And what of the curse put on the region by infamous voodoo priestess Julia Brown in the early 1900s? Jericho encounters compelling proof from eyewitnesses, physical evidence and a startling revelation from BEYOND the grave. #MonsterHuntGHOST ADVENTURES - "Graveyard of the Pacific"Four-Part MiniseriesPremieres Saturday, October 6 at 9 p.m. ET/PTIn this special four-part miniseries event, Zak Bagans, Aaron Goodwin, Billy Tolley and Jay Wasley head to the "Graveyard of the Pacific" - a treacherous nautical region within the Pacific Northwest where the freshwater of the Columbia River meets the Pacific Ocean. Here, DARKNESS plagues both land and sea - the ocean has claimed thousands of shipwrecks and countless lives, while unexplained deaths, diseases, fires and murders have impacted areas around the shoreline. The investigation takes the team to multiple haunted locations - from the UNDERGROUND tunnels weaving beneath the city of Astoria, Oregon, and the port city''s Norblad Hostel to the Fort Stevens Military Base outside of town where dangerous entities are believed to haunt various sites. The investigation culminates at the North Head Lighthouse in Washington, which bore witness to some of the most tragic shipwrecks of this watery graveyard. #GhostAdventuresGHOST ADVENTURES LIVEFour-Hour Live InvestigationPremieres Wednesday, October 31 beginning at 8 p.m. ET / 5 p.m. PTThis Halloween, join the "Ghost Adventures" team for the ultimate Halloween night event - a four-hour, live investigation inside Zak Bagans'' Las Vegas Haunted Museum. On the one-year anniversary of its opening, Bagans and the "Ghost Adventures" crew, along with special guests, will investigate the museum that contains hundreds of haunted objects, some so frightening and powerful they can''t even be touched. It''s sure to go down as one of the most terrifying nights in paranormal history. Through an on-location live video stream, viewers can monitor all of the "Ghost Adventures Live" activity on Travel Channel''s Facebook Live platform and comment on any findings in real time. Fans can follow Travel Channel''s social media pages for exciting giveaways and to join a special pre-"Ghost Adventures Live" Q&amp;A session with Zak Bagans and the team. #GhostAdventuresLiveNEW SEASONPARANORMAL SURVIVORPremieres Sunday, September 9 at 9 p.m. ET/PT (continues through October)"Paranormal Survivor" will take you through terrifying real-life encounters with the supernatural. Hear from those who''ve faced these feared spirits - and watch dramatic recreations that lure people back to the scenes of these harrowing confrontations. #ParanormalSurvivorNEW EPISODESMOST TERRIFYING PLACES IN AMERICAPremieres Sunday, September 30 at 11 p.m. ET/PT (continues through October)Be afraid. Be very afraid. Evil lurks in every corner of the country. "Most Terrifying Places in America" takes you on a treacherous trip across the nation''s most horrifying haunts. Take a ride on the dire side as we uncover the most bone-chilling manors and inns, and visit real life ghost towns so cursed shivers will run down your spine. Join us as we stop at the nation''s scariest attractions, which will leave you feeling like a wide-eyed, freaked-out kid again, and come along as we unearth the most frightening forests, forts and freeways. #MostTerrifyingPlacesABOUT TRAVEL CHANNELFor virtual and active travelers who want to go on a thrilling quest; taste other cultures; enjoy the mystery of the unexplored; get a dose of epic adventure; there is no better daily escape than Travel Channel. Reaching more than 82 million U.S. cable homes, Travel Channel is the world''s leading travel media brand. Fans also can visit Travel Channel for more information or interact with other fans through Facebook, Twitter, Pinterest and Instagram. Travel Channel is owned by Discovery, Inc., a global leader in real life entertainment whose portfolio also includes Discovery Channel, HGTV, Food Network, TLC, Investigation Discovery, and OWN: Oprah Winfrey Network.</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/ghost-adventures-locks-down-travel-channels-spook-filled-ghostober-event', 1535342400, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('gil-conceives-co-parenting-format', 'Gil Conceives Co-Parenting Format', 'gil-conceives-co-parenting-format', 'Gil Formats, the development and distribution arm of Israel’s Gil Productions, has linked up with US prodco My Entertainment to create a format about the growing phenomenon of co-parenting.Pregnant…', '<p>Gil Formats, the development and distribution arm of Israel’s Gil Productions, has linked up with US prodco My Entertainment to create a format about the growing phenomenon of co-parenting.Pregnant &amp; Platonic will launch at Mipcom next week and will centre on women and men who are looking to have a child without first falling in love. The format was inspired by the personal experience of Gil Formats CEO Assaf Gil, who had his first child this year with a co-parent.“It is a radical new way to start a family and the stakes couldn’t be higher – two strangers making a lifelong commitment to have and raise a child together. It’s platonic parenting and this is the new modern family,” Gil Formats said in a statement.Pregnant &amp; Platonic will see each participant meet three potential partners that have been hand-selected for them by a team of experts, and go through an intensive parenting training to help determine if their values and parenting styles are compatible.Once they choose a partner to have a child with, the series will follow the couples over the course of a year as they face numerous challenges before they can turn their dreams of becoming parents into a reality. Each story aims to end with a baby being born.</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/gil-conceives-co-parenting-format', 1476072000, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('gil-formats-inks-pregnant-and-platonic-deals', 'Gil Formats Inks Pregnant and Platonic Deals', 'gil-formats-inks-pregnant-and-platonic-deals', 'Gil Formats inks Pregnant and Platonic deals Tel Aviv-based distributor Gil Formats has penned four deals with prodcos across Europe to produce its newest format Pregnant and Platonic .Finestripe P…', '<p><strong>Gil Formats inks <em>Pregnant and Platonic </em>deals</strong>Tel Aviv-based distributor Gil Formats has penned four deals with prodcos across Europe to produce its newest format <em>Pregnant and Platonic</em>.Finestripe Productions in the UK, Endemol Shine Germany, This Is Nice Group in Sweden and Bulldog TV in Spain have signed on to produce the social experiment format in their respective territories.The series chronicles the lives of men and women looking to birth a child without becoming romantically involved. Cameras will follow selected participants – hand-selected for them by a team of experts – over the course of a year as they face the challenges of becoming a co-parent. Each story will hopefully culminate with a child being born.<em>Pregnant and Platonic </em>was co-developed by Gil Formats and New York’s MY Entertainment.The format was inspired by the personal experience of Gil Formats CEO Assaf Gil who had his first child in 2016 with a co-parent.</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/gil-formats-inks-pregnant-and-platonic-deals', 1483592400, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('gil-formats-sends-pregnant-platonic-to-australia-and-france', 'Aussie, French Prodcos Get Pregnant', 'gil-formats-sends-pregnant-platonic-to-australia-and-france', 'Tel Aviv-based sales firm Gil Formats has sold its fact-ent format Pregnant &amp; Platonic to production companies in Australia and France. Aussie producer Eureka Productions and French studio Ah! …', '<p>Tel Aviv-based sales firm Gil Formats has sold its fact-ent format <em>Pregnant &amp; Platonic </em>to production companies in Australia and France. Aussie producer Eureka Productions and French studio Ah! have signed on to produce the social experiment format in their respective territories.The series chronicles the lives of men and women looking to birth a child without becoming romantically involved. Cameras will follow selected participants – hand-selected for them by a team of experts – over the course of a year as they face the challenges of becoming a co-parent. Each story will hopefully culminate with a child being born.Co-developed by Gil Formats and New York’s MY Entertainment, the format was inspired by the personal experience of Gil Formats CEO Assaf Gil who had his first child in 2016 with a co-parent.The format has now been taken on in six territories, including the UK, Spain, Sweden and Germany.</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/gil-formats-sends-pregnant-platonic-to-australia-and-france', 1490760000, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('high-noon-optomen-lmno-grb-bunimmurray-join-npa', 'MY Entertainment, High Noon, GRB, Bunim/Murray Join NPA', 'high-noon-optomen-lmno-grb-bunimmurray-join-npa', 'Fourteen more production companies from New York and Los Angeles have joined the Non-Fiction Producers Association (NPA), the fledgling non-profit trade group dedicated to growing non-fiction indus…', '<p>Fourteen more production companies from New York and Los Angeles have joined the Non-Fiction Producers Association (NPA), the fledgling non-profit trade group dedicated to growing non-fiction industry.Bunim/Murray Productions, Evolution Media, Eyeworks USA, Go Go Luckey Entertainment, GRB Entertainment, High Noon Entertainment, Lighthearted Entertainment, LMNO Productions, MY Entertainment, Optomen, Renegade 83, Sharp Entertainment, The Ebersol Lanigan Company and Zodiak New York have all joined the organization, it announced today (August 27).The news comes after the NPA launched last month with eight companies on board: Atlas Media Corp, Big Fish Entertainment, Jane Street Entertainment, Leftfield Pictures, Loud TV, Magilla Entertainment, Original Media and True Entertainment.At launch, the NPA said it aims to promote best practices that will “ensure production employees, independent contractors, vendors and other stakeholders have a voice and platform for meaningful discourse that can encourage and contribute to the continued success and welfare of all parties within the non-fiction television industry.”In addition, the organization said today (August 27) that it has also formed a six-member executive committee and a 15-member board of directors, although the names of those on the committee and the board have yet to be released.The board’s first meeting will be held on September 10 in New York, where the group will establish its first set of initiatives.“We are gratified by the continuing and growing positive response to the formation of the NPA, and are delighted to welcome these new companies – from the East and West Coasts – to our ranks,” said NPA exec director Rick Feldman (pictured above).“The NPA now includes 22 of the industry’s top television producers, and we are currently in talks with more production companies that have expressed serious interest.”In a statement, the organization said: “For several years now, the Writers Guild of America, East has worked to raise awareness among elected officials and the general public of the difficult working conditions faced by people working in non-fiction/reality television.“We hope the NPA and its new members will address the serious workplace issues faced by their employees. The Writers Guild of America, East has been working closely with the thousands of writer-producers who work so hard to make non-fiction programs successful. These efforts have brought company-paid health benefits, paid time off, minimum compensation levels, and other important protections to many producers and associate producers.“We look forward to working closely with the NPA and prodcos to extend these improvements industry-wide.”</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/high-noon-optomen-lmno-grb-bunimmurray-join-npa', 1409112000, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('hollywoods-mr-antiques-is-the-go-to-man-for-a-listers-in-search-of-something-special', 'Hollywood''s Mr Antiques is the go-to man for A-listers in search of something special', 'hollywoods-mr-antiques-is-the-go-to-man-for-a-listers-in-search-of-something-special', 'Tattooed eccentric Billy Leroy presides over an emporium in a small corner of Brooklyn which regularly sells vintage furnishings to the likes of Leonardo DiCaprio, Dustin Hoffman, Cameron Diaz and …', '<p>Tattooed eccentric Billy Leroy presides over an emporium in a small corner of Brooklyn which regularly sells vintage furnishings to the likes of Leonardo DiCaprio, Dustin Hoffman, Cameron Diaz and Keanu Reeves.This small corner of New York is where the weird, wacky and wonderful collide, presided over by a tattooed eccentric selling unique treasures to the stars.With his red-tinted glasses and trademark waistcoat, Billy Leroy is the go-to man for Hollywood A-listers in search of something special to furnish their mansions and luxury apartments.His emporium in Brooklyn offers up everything from vintage subway signs and silk-lined mahogany coffins to a never-seen-before Alfred Hitchcock film.Stars such as Leonardo DiCaprio, Dustin Hoffman, Cameron Diaz and Keanu Reeves regularly look for finds at Billy’s Antiques &amp; Props.He says: “I had a really amazing Hannibal Lecter painting that Leo was interested in. He would come over on his bike and drop in just to look at it.“Keanu is another one who comes in to browse. He dresses down, clothes hanging off him, looking a bit down and out – a lot of the time you can’t even tell it’s him, he’s really incognito.“And I remember the time I looked up to see Reece Witherspoon and Jake Gyllenhaal making out in my doorway! It was when they were dating. Celebrities come to my store because they get treated and can act like regular folk.”Billy has run his outlet since the 90s, first in Manhattan before soaring rents drove him out after two decades and he moved it across the East River to Brooklyn.Now he has invited the TV cameras to capture the craziness of his life for the Discovery+ series Billy Buys Brooklyn, which also features his wife Lorraine.Billy says he is a dealer, not a collector, and that anything in his possession is for sale – including items in his own home.“I’ll sell the shoes off my feet,” he says with a laugh during a Zoom call from his store. “Everything has a price!”The key to his success, it seems, is that no matter who walks through the door, everyone is on the same level.Billy says: “I treat my celebrity customers like regular people, because I noticed as soon as you start gushing and asking them ridiculous questions, they kind of back off. They like coming to my store because they know they won’t get hassled.”So he never gets star struck? “The only people who would leave me star struck are the likes of Michael Caine or Sean Connery, bless his soul,” he says. “But sadly Michael hasn’t been in and Sean never visited.”One star who did make an impression was 83-year-old Dustin Hoffman, who managed to resist a vintage coffin that Billy cheekily tried to flog him.“Sadly, he didn’t buy it,” says Billy. “Midnight Cowboy is one of my favourite movies. So when he came in with his son Jake, I said, ‘Oh, it’s Ratso Rizzo!’ He thought it was funny. He’s talkative. He would tell me about the time he roomed with Gene Hackman in the 1950s, and they had a cold water flat.“Can you believe it? They had no hot water. It shows they haven’t always been rich – most of them started from nothing.“Dustin’s a wealth of information, such an icon, and just a really nice guy, really humble.”Scottish actor Gerard Butler, 51, had just celebrated the release of 2006 action epic 300 when he turned up looking to furnish his new flat. Billy says: “He had a big welt on his nose. I was like, ‘What happened?’ and he said, ‘These guys in bars often challenge me because of 300. If you play a macho part, they’ll challenge you’.“He was with his decorator and they started buying a lot of stuff. He must have made a lot of money from that movie because he didn’t barter!“I went to his Midtown apartment, everything was done like a Roman bath with columns, like something out of the ancient world. He also bought a big meteorite that was five billion years old!”Another windfall came when singer Usher, 42, arrived, surrounded by security who wanted Billy to close his doors so the star could shop in peace.“I didn’t mind because I realised it was going to be a big pay day,” says Billy. “My head was going ding, ding, ding! He was a really nice guy and he bought a ton of stuff, including a cool phone booth from the 1940s.”</p><p>Some do drive a hard bargain, no matter how wealthy they are. “The richer they are, the more they barter,” Billy says. “They’re ruthless.”Not for nothing has actress-turned-fashion tycoon Mary-Kate Olsen, 35, amassed an estimated £500million fortune. Billy says: “She bought loads of stuff, she really went for that beaten up, shabby chic look.About six months later her assistant called me and said, ‘Mary-Kate would like to sell you back the stuff she bought’. I was really glad to have got rid of it, so I told her to just give it away!”Billy counts stars such as Daniel Craig and Johnny Depp as friends, and now he is hoping his new show might land him a royal customer – as he has heard Prince Harry is a fan one of his previous US shows, Baggage Battles.Billy says: “Maybe one day Harry will come in. That would be great.”</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/hollywoods-mr-antiques-is-the-go-to-man-for-a-listers-in-search-of-something-special', 1627876800, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('how-cooking-in-conflict-zones-changed-la-chef-michael-voltaggio', 'How Cooking in Conflict Zones Changed LA Chef Michael Voltaggio', 'how-cooking-in-conflict-zones-changed-la-chef-michael-voltaggio', 'Michael Voltaggio is no stranger to television cameras. The Los Angeles-based chef/owner of Ink and InkSack won the sixth season of Top Chef, which involved cooking in a moving train car and over a…', '<p>Michael Voltaggio is no stranger to television cameras. The Los Angeles-based chef/owner of Ink and InkSack won the sixth season of Top Chef, which involved cooking in a moving train car and over a fire pit among its various challenges. But his latest television project — the upcoming Travel Channel series Breaking Borders — is nothing like Bravo''s reality competition, even though he sometimes found himself cooking in difficult settings. "The challenging aspect of it was very similar, but in Top Chef that was purposely staged to be that way," he tells Eater. With Breaking Borders, they''re not trying to set me up to fail, they''re not trying to create some weird challenge to go through." He clarifies: "This is real, it''s not a reality TV show.""This is real, it''s not a reality TV show."As previously reported, Breaking Borders brings Voltaggio and Peabody Award-winning correspondent Mariana van Zeller to various "conflict zones" around the world, including Belfast, Cairo, Cuba, Rwanda, and more. As the show''s website explains, van Zeller "digs deeper into the issues" while Voltaggio "goes on a culinary adventure, collecting ideas and ingredients to create an unbelievable meal inspired by the people he has met." Voltaggio and van Zeller then gather people from both sides of the conflict around the table to talk and to enjoy the meal Voltaggio has created for the occasion.Voltaggio says cooking this meal is, for him, the most challenging part of the show. After experiencing the local cuisine and ingredients, he sets about devising and executing the menu. "I don''t have my staff, I don''t have my kitchen, I don''t have my equipment," he says. "I have a few knives rolled up in canvas bag, a pen, and a piece of paper. I just go and I use my instincts as a cook." But sometimes the conditions aren''t exactly ideal for cooking a large meal. "When I got to Egypt, the economy was so bad that the guy''s restaurant that I was cooking in had been out of business for years," Voltaggio says. "The only piece of equipment that I really had to work with in his restaurant was a chimney on the rooftop and a couple of burners that I bought in the street... That''s what was available to me, and that''s a real part of the journey.""We''re not creating world peace. We''re out there just helping people have an opportunity to tell their stories."Voltaggio has high hopes for the show''s ability to make a meaningful impact on viewers. "I hope people watch the show, start their own conversations, and it gets bigger than that one dinner table," he says. "We''re not creating world peace. We''re out there just helping people have an opportunity to tell their stories."These stories have certainly left an impact on Voltaggio. Despite the occasional hardships setting up a working kitchen, the chef says the biggest surprise during filming was not the cooking conditions. "The most memorable surprises that are embedded in my brain, the ones that I won''t ever forget, are the stories that come out of people''s mouths," he says. "The biggest surprise is, a) their ability to tell these stories and b) their ability to forgive one another for what''s happened in the past... The guests that are sitting at the table, in some cases, were once told to kill each other. And [they''re now able to] sit down and have a meal with each other and be able to look at each other in the face and say, ''I forgive you'' or ''We forgive the situation.''"Voltaggio has also brought these experiences back to his restaurants. From a culinary perspective, Voltaggio says his exploration has been wonderfully educational. "You often get stuck in your kitchen and obviously research is a big part of learning, but going out and experiencing other things is even a better way to do research," he explains. He has also taken "little tricks and pieces of equipment, flavors, and ingredients" from his travels around the world into his kitchen — for example, a dish of shawarma-spiced beef cheek with eggplant mutabal on the current Ink menu was inspired by Voltaggio''s trips to Israel, Palestine, Lebanon, and Egypt.There''s another key lesson Voltaggio has learned from filming: patience and forgiveness. "I''m learning a lot of qualities that chefs might not necessarily have, because we do work in stressful environments," he says. "But my stressful environment in the kitchen doesn''t compare to the stressful lives that these people I''m meeting around the world are actually going through every day."Breaking Borders premieres Sunday, March 15 on the Travel Channel. The episode takes Voltaggio and van Zeller to the West Bank and in the exclusive preview below, Palestinian and Israeli settlers gather around the dinner table for Voltaggio''s location-inspired menu.</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/how-cooking-in-conflict-zones-changed-la-chef-michael-voltaggio', 1425618000, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('investigation-discovery-orders-second-season-of-las-vegas-law', 'Investigation Discovery Orders Second Season of LAS VEGAS LAW', 'investigation-discovery-orders-second-season-of-las-vegas-law', 'Investigation Discovery (ID) has greenlit a second season of LAS VEGAS LAW, offering exclusive access to Clark County District Attorney Steve Wolfson and his powerhouse team of prosecutors as they …', '<p><a href="http://www.broadwayworld.com/bwwtv/tvnetworks/Investigation-Discovery">Investigation Discovery</a> (ID) has greenlit a second season of LAS VEGAS LAW, offering exclusive access to Clark County District Attorney Steve Wolfson and his powerhouse team of prosecutors as they pursue justice in Las Vegas.Production is already underway on six episodes expected to premiere in 2017 only on ID. Picking up where the first season left off, season two of LAS VEGAS LAW will continue to document current criminal cases as they unfold, intimately capturing all angles of the trial process from both the prosecution and the defense teams. Shot in cinéma vérité and featuring surveillance footage, crime scene photography, and body and dash cam footage, the series immerses viewers in the high stakes, immensely dramatic environment that makes Vegas distinctive - and its crimes even more so."What sets apart LAS VEGAS LAW from other courtroom dramas on television is its unique, exclusive access to every leg of the legal journey, from the prosecutors'' initial assessment of the crime scene to the judges'' final sentencing," said Kevin Bennett, general manager of Investigation Discovery. "Cameras are out in the field right now as summer heats up in Sin City, capturing real-life cases from the moment they hit D.A. Wolfson''s desk."LAS VEGAS LAW is produced for <a href="http://www.broadwayworld.com/bwwtv/tvnetworks/Investigation-Discovery">Investigation Discovery</a> by MY Entertainment. For MY Entertainment, Michael Yudin, Joe Townley, Wil Surratt and Wayne Allyn Root are executive producers, with Greg Klein and Jon Grosskopf as co-executive producers. For Investigation Discovery, Eugenie Vink is senior executive producer, Sara Kozak is senior vice president of production, Kevin Bennett is general manager, and Henry Schleiff is Group President of Investigation Discovery, <a href="http://www.broadwayworld.com/bwwtv/tvnetworks/AMERICAN-HEROES-CHANNEL">AMERICAN HEROES CHANNEL</a> and Destination America.About <a href="http://www.broadwayworld.com/bwwtv/tvnetworks/Investigation-Discovery">Investigation Discovery</a> Investigation Discovery (ID) is the leading mystery-and-suspense network on television. From harrowing crimes and salacious scandals to the in-depth investigations and heart-breaking mysteries behind these "real people, real stories," the always revealing network challenges our everyday understanding of culture, society and the human condition. One of our nation''s fastest growing cable networks, ID delivers the highest-quality programming to 85 million U.S. households and is available in both high definition (HD) and standard definition (SD). For more information, please visit InvestigationDiscovery.com, facebook.com/InvestigationDiscovery, or twitter.com/DiscoveryID. <a href="http://www.broadwayworld.com/bwwtv/tvnetworks/Investigation-Discovery">Investigation Discovery</a> is part of Discovery Communications (Nasdaq: DISCA, DISCB, DISCK), the world''s #1 pay-TV programmer reaching nearly 3 billion cumulative subscribers in 220 countries and territories.About MY Entertainment (www.myentertainment.tv) MY Entertainment is a successful independent production company launched in 2000 by veteran TV producer and advertising executive, Michael Yudin. In addition to creating and producing compelling content, MY Entertainment has become known for pioneering new business models with advertisers, broadcasters and production companies in the US and around the world. MY Entertainment''s current series include; the 12th season of Ghost Adventures, for Travel Channel, Las Vegas Law for Investigation Discovery, <a href="http://www.broadwayworld.com/bwwtv/tvshows/Baggage-Battles">BAGGAGE BATTLES</a> for Scripps International Networks, Paranormal Museum and You Only Live Once for <a href="http://www.broadwayworld.com/bwwtv/tvnetworks/Travel-Channel">Travel Channel</a>and Sherman''s Warriors for <a href="http://www.broadwayworld.com/bwwtv/tvnetworks/NBC">NBC</a> Sports Digital platform. With offices in NY and LA, the company currently has projects in development with Discovery, History, Travel, Lifetime, WE tv, Travel and Discovery Science. MY Entertainment is perhaps best known for the long running hit series Pros vs. Joes.</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/investigation-discovery-orders-second-season-of-las-vegas-law', 1471320000, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('investigation-discoverys-sin-city-justice-offers-exclusive-access-to-las-vegas-prosecutors', 'Investigation Discovery’s Sin City Justice Offers Exclusive Access To Las Vegas Prosecutors', 'investigation-discoverys-sin-city-justice-offers-exclusive-access-to-las-vegas-prosecutors', '(Silver Spring, Md.)— In Las Vegas, a city where nearly everything is a gamble, the Clark County District Attorney''s Office is as close to a sure thing as it gets. Led by District Attorney Steve Wo…', '<p>(Silver Spring, Md.)— In Las Vegas, a city where nearly everything is a gamble, the Clark County District Attorney''s Office is as close to a sure thing as it gets. Led by District Attorney Steve Wolfson, this diverse and dedicated group of prosecutors rarely ever hears the words "Not Guilty" as they work tirelessly alongside law enforcement to pursue justice in their community. Investigation Discovery’s (ID) SIN CITY JUSTICE – formerly known as LAS VEGAS LAW – grants viewers exclusive access to D.A. Wolfson’s powerhouse team as they prepare and prosecute major criminal cases.Shot in cinéma vérité and featuring surveillance footage, police interrogation video, and photography never released before, the series immerses viewers in the high stakes, immensely dramatic environment that makes Vegas distinctive – and its crimes even more so. The six-episode first season of SIN CITY JUSTICE premieres Thursday, June 8 at 10/9c only on ID.With more than 60,000 cases a year, including high-profile homicides, robberies, gang-related crimes and assaults on the Strip, these aren’t stories pulled from a Hollywood script. They happen to real people just trying to live and let loose under the big lights of Sin City. The premiere episode “Rage Against the Machine,” on Thursday, June 8 at 10/9c, captures the courtroom drama that centered around one of Sin City''s hottest couples, adult film superstar Christy Mack and mixed martial artist Jon Koppenhaver, a.k.a. War Machine.Their relationship blew up social media. Their passion was more intense than the neon on Las Vegas Boulevard. But after they broke up, War Machine brutally attacked and sexually assaulted Mack. As the case came to trial amidst a media circus and national headlines, SIN CITY JUSTICE’s cameras followed the prosecutors’ battle to convince a jury that Mack truly was a victim despite her past as an adult-film star.Other cases featured this season in SIN CITY JUSTICE are:--“All for Eighty Dollars” premieres Thursday, June 15 at 10/9cNo parent should have to bury their child. In 2013, Ivan Arenas had to do just that when his beloved 15-year-old son Marcos was targeted, robbed, then run over by a car and killed as he fought to hold onto the iPad Ivan bought for him. His killers went on the run, selling the iPad for $80 along the way, but were finally apprehended. Now Chief Deputy District Attorneys Jacqueline Bluth and Agnes Lexis hope to keep co-defendants, Michael Solid and Jacob Dismont, behind bars for murder as Marcos''s large extended family witnesses the twists and turns in this dramatic trial.--“An Uncontrollable Rage” premieres Thursday, June 22 at 10/9cIt was overkill when Robin Jenkins was violently stabbed to death by her fiancé, David Frostick. Robin''s family was devastated when they received the news, that turned to frustration as they waited seven years for justice. Meanwhile in another case, Nicholas Crystal and his girlfriend Nina Spiro use the ruse of her fake pregnancy to steal a man''s car, with Crystal nearly beating the man to death. Days later, Crystal violently attacks a second victim before he and Spiro are apprehended. With twists and turns, the DA''s office goes to trial on both cases.--“Making a Statement” premieres Thursday, June 29 at 10/9cAfter a woman is raped in a Vegas parking lot, she can''t identify her attacker and the case goes cold until a DNA hit reveals him to be Calvin Smock. The woman bravely testifies, but prosecutors worry about a few inconsistencies in her story. Meanwhile in another case, two exotic dancers get into a violent fight over a client. Who will the jury believe: the victim who had a glass smashed across her face but who''s also been arrested for domestic violence, or the attacker who’s a famous porn star with prior criminal record?--“Blood Brothers” premieres Thursday, July 6 at 10/9cWhen John and Anita Sullivan are killed by a drunk driver and their bodies burned beyond recognition, their adult sons are destroyed. Their grief becomes anger when the driver, Matthew Dalrymple, flees while bail is being posted. Taking matters into their own hands, the brothers turn to social media to help track down Dalrymple. Now with Dalrymple in custody, will these brothers get their justice? Meanwhile in a difficult murder case that first resulted in a mistrial, two dedicated prosecutors must try the case a second time, seeking the Death Penalty, as brother turns against brother in court.--“Betrayed” premieres Thursday, July 13 at 10/9cProsecutors call Easter Williams a “miracle” for surviving a gunshot to the head after catching her husband Gabrial Williams with another woman in their bedroom. Put on life support, she not only survives a risky surgery but regains her memory to point the finger at her husband and his lover, Maira Sepulveda. Now the question is: will this adulterous couple stick to their story that Easter shot herself, or will they turn on one another in a dramatic trial filled with twists and turns?SIN CITY JUSTICE is produced for Investigation Discovery by MY Entertainment. For MY Entertainment, Michael Yudin, Joe Townley, and Wayne Allyn Root are executive producers, with Greg Klein and Jon Grosskopf as co-executive producers. For Investigation Discovery, Eugenie Vink is senior executive producer, Sara Kozak is senior vice president of production, Jane Latman is executive vice president of development, Kevin Bennett is general manager, and Henry Schleiff is Group President of Investigation Discovery, American Heroes Channel and Destination America.</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/investigation-discoverys-sin-city-justice-offers-exclusive-access-to-las-vegas-prosecutors', 1494907200, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('is-it-october-already-travel-channel-embraces-the-unknown-in-its-third-annual-ghostober-event', 'Is It October Already? Travel Channel Embraces the Unknown in Its Third Annual "Ghostober" Event', 'is-it-october-already-travel-channel-embraces-the-unknown-in-its-third-annual-ghostober-event', 'NEW YORK - (September 14, 2020) This might just be the year to buy lots of extra candy and settle in for "Ghostober," Travel Channel''s third annual paranormal programming event.No need to leave the…', '<p>NEW YORK - (September 14, 2020) This might just be the year to buy lots of extra candy and settle in for "Ghostober," Travel Channel''s third annual paranormal programming event.No need to leave the house when Halloween reigns all month long, taking viewers on spine-chilling adventures to the other side - where tales of poltergeists, ghostly creatures, demons and even a few legends will keep you company. Filled with a creepy mix of buzzy new specials, boldfaced names and returning favorites, "Ghostober" has all the thrills and chills on lockdown.While we are all living with many unknowns, Travel Channel conjures up over-the-top specials exploring the very topic of the real unknown. While paranormal programming is scheduled throughout October, Ghostober culminates with "7 Nights of Fright." The top 20 of the world''s spookiest unexplained videos kickstarts the week on Sunday, October 25 at 9 p.m. ET/PT, with the two-hour countdown "Paranormal Caught on Camera: Top 100." Included in this week''s lineup of supersized specials are new Shock Docs focusing on two of our nation''s most terrifying tales of horror - "Amityville Horror House," premiering on Monday, October 26 at 9 p.m. ET/PT and "The Exorcism of Roland Doe," premiering on Tuesday, October 27 at 9 p.m. ET/PT. Then, fans will celebrate the season with many of Travel Channel''s talent featured in the new "Shock Docs" tell-all holiday special, "This is Halloween," premiering Wednesday, October 28 at 9 p.m. ET/PT.As the calendar creeps closer to All Hallows'' Eve, we crank up the terror with over-the-top tricks and treats. In the two-hour special, "Ghost Adventures: Horror at Joe Exotic Zoo," premiering Thursday, October 29 at 9 p.m. ET/PT, Zak Bagans and the "Ghost Adventures" crew go inside the infamous Greater Wynnewood Exotic Animal Park to investigate sinister accounts of ghostly activity. The special is then followed by the Season Two return of "The Holzer Files," reopening famed ghost hunter Hans Holzer''s original case files, at 11 p.m. ET/PT.The goosebumps continue with a sneak peek of the new season of "Portals to Hell," starring Katrina Weidman and Jack Osbourne, on Friday, October 30 at 8 p.m. ET/PT. The duo investigates what might just be the most haunted place in all of Connecticut. And then, in a special two-hour holiday treat, the whole Osbourne family joins in on the fun. Adamant on truly living up to their position as America''s first family of darkness, Jack Osbourne takes Ozzy, Sharon and Kelly on their first-ever paranormal investigation in "The Osbournes: Night of Terror," premiering at 9 p.m. ET/PT. Not only are they going to hunt ghosts together ... but they''re going to love it.Travel Channel wraps up "Ghostober" on Halloween night with the ultimate series crossover featuring superstar paranormal investigators from two of the network''s hit shows, "Ghost Nation" and "Kindred Spirits." The ghost-hunting teams reunite for the first time in nearly a decade to explore frightening activity inside an illustrious Newport, Rhode Island, mansion in "Ghost Nation: Reunion in Hell," premiering Saturday, October 31 at 8 p.m. ET/PT. And the programming event bows with a chilling new episode of "Destination Fear" on Saturday, October 31 at 10 p.m. ET/PT, where the team will spend a terrifying night inside the abandoned Old Crow Distillery in Frankfort, Kentucky."Halloween is Travel Channel''s Superbowl, and with more people at home than ever before, we plan to deliver an over-the-top slate of original programming. We are the only network super-serving this mega popular genre to its superfans, featuring the superstars of the paranormal field and beyond," said Matthew Butler, general manager, Travel Channel.The "Ghostober" 2020 celebration is back on TravelChannel.com and Travel Channel''s Facebook, Twitter and Instagram pages. Fans can check out exclusive content from their favorite shows, a new exclusive web series, "Up Close &amp; Paranormal," with the cast of "Ghost Nation" and "Kindred Spirits," behind-the-scene videos, cast interviews, photos and more. Viewers can also stream a variety of Travel Channel''s series, including past seasons of "Ghost Adventures," on the Travel Channel Go app.</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/is-it-october-already-travel-channel-embraces-the-unknown-in-its-third-annual-ghostober-event', 1601352000, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('josh-elliott-exits-cbs-cable-news-host-launches-twitter-attack-abc-and-people-team-for-princess-di-doc', 'MY Entertainment Announces Slate of New Crime Shows', 'josh-elliott-exits-cbs-cable-news-host-launches-twitter-attack-abc-and-people-team-for-princess-di-doc', 'Factual production specialist MY Entertainment announced a slate of crime-driven projects, including a co-production with Zak Bagans Entertainment telling the story of killer/cult leader Charles Ma…', '<p>Factual production specialist MY Entertainment announced a slate of crime-driven projects, including a co-production with Zak Bagans Entertainment telling the story of killer/cult leader Charles Manson through the eyes of his grandson. A development deal with retired police lieutenant Randy Sutton for Behind the Badge will explore the police’s involvement in cultural moments and criminal investigations.</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/josh-elliott-exits-cbs-cable-news-host-launches-twitter-attack-abc-and-people-team-for-princess-di-doc', 1487048400, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('korean-formats-agency-something-special-strikes-development-deal-with-my-entertainment', 'Korean Formats Agency Something Special Strikes Development Deal With MY Entertainment', 'korean-formats-agency-something-special-strikes-development-deal-with-my-entertainment', 'As Korean formats continue their international expansion, Michael Yudin ’s MY Entertainment has partnered with Seoul-based formats agency Something Special to cultivate more creative IP.“Ghost Adve…', '<p>As Korean formats continue their international expansion, <a href="https://variety.com/t/michael-yudin/">Michael Yudin</a>’s <a href="https://variety.com/t/my-entertainment/">MY Entertainment</a> has partnered with Seoul-based formats agency Something Special to cultivate more creative IP.“Ghost Adventures” production outfit MY Entertainment has struck a co-development deal with the Korean formats group, which was founded by Hwang Jin Woo (pictured, right), president and executive director, and Kim InSoon (left), executive VP and head of content. Under the deal, the companies will develop three unscripted formats for major U.S. networks and streaming platforms as well as the international marketplace. Ever since the success of Fox’s breakout hit “The Masked Singer” (now on Season 6), Korean unscripted IP has been a hot commodity in the international TV market.The trio of formats span fast-paced primetime game show “Smashed Hits,” dating show “Inseparables” and fear-based competition series “The Quizzy Horror Show.” The shows all stem from a Korean Creative Content Agency (<a href="https://variety.com/t/kocca/">KOCCA</a>) initiative in May that brought together top Korean producers to “spark creativity.” Three of those producers and their ideas were selected by MY Entertainment as top formats for U.S. and international success.“Smashed Hits” (working title) finds contestants working to identify popular songs that have been mixed together and creatively reinvented so that they’re barely recognizable. Each episode will feature guest appearances by the biggest names in the music industry who perform other artists’ hits in surprising ways. The format is produced by Eunseol Mo, whose credits include “Fantastic Duo” (SBS) and “Qualification of Men” (KBS).Elsewhere, “Inseparables” (w/t) tests the patience of couples who — in order to win their dream house — are locked down together in one place as they attempt to overcome the issues presented by smaller and smaller quarters. Producer is Kim Sehwa, creative director of long-running quiz show “Scholarship Quiz” (EBS) and a producer on “1 vs 100” (KBS).Finally, “The Quizzy Horror Show” (w/t) dares contestants to turn their worst fears into cash prizes by asking them not to blink at any heart-beating moment. Producer is Kim Jiyoon, whose credits include “My Little Television” and “Cashback” (CJ E&amp;M, co-developed with Bunim/Murray).Something Special’s Hwang and Kim said: “We are thrilled to bring Something Special together with MY Entertainment. Our talented Korean producers look forward to collaborating with Michael and his extraordinary team at MY Entertainment. They have long been a prominent industry player with their eyes on the Korean market and it is the perfect time for us to finally walk down the aisle especially when Korean creativity is being recognized more than ever.”Yudin added: “Coming on the heels of our successful international market collaboration with Seoul Broadcasting System (SBS) and MTV for the ultimate reality competition show, ‘The Power,’ our new partnership with Something Special marks another benchmark for MY Entertainment’s strategy of expanding its activities with leaders in the Korean creative production community.”</p><p>‍<a target="_blank" href="https://variety.com/2021/tv/global/korean-formats-my-entertainment-something-special-1235128068/">Original Release: VARIETY</a></p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/korean-formats-agency-something-special-strikes-development-deal-with-my-entertainment', 1639458000, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('korean-formats-including-the-quizzy-horror-show-head-to-u-s-after-something-special-strikes-deal-with-my-entertainment', 'Korean Formats Including ‘The Quizzy Horror Show’ Head To U.S. After Something Special Strikes Deal With My Entertainment', 'korean-formats-including-the-quizzy-horror-show-head-to-u-s-after-something-special-strikes-deal-with-my-entertainment', 'EXCLUSIVE : A trio of Korean unscripted formats are heading to the U.S. and international marketplace after Korean company Something Special struck a deal with Breaking Borders producer My Entertai…', '<p><strong>EXCLUSIVE</strong>: A trio of Korean unscripted formats are heading to the U.S. and international marketplace after Korean company <a href="https://deadline.com/tag/something-special/">Something Special</a> struck a deal with Breaking Borders producer <a href="https://deadline.com/tag/my-entertainment/">My Entertainment</a>.</p><p>The two companies are co-developing <em>The Quizzy Horror Show, Smashed Hits </em>and<em> Inseparables</em> as part of the partnership.</p><p>It comes after the Korean Creative Content Agency (KOCCA) funded a scheme to help local producers bring their formats to U.S. networks and streaming platforms.</p><p><em>Smashed Hits</em> is a gameshow that sees contestants trying to guess popular songs that have been mixed together and reinvented so they are barely recognizable. Each episode will feature guest appearances from pop stars and musicians by performing other artists’ hits in very surprising ways. It comes from Eunseol Mo, who has produced series including <em>Fantastic Duo </em>and<em> Qualification of Men.</em></p><p><em>Inseparables</em> is a competition show that will test the patience of participating couples, spending more time together due to the pandemic, as they attempt to overcome the issues presented by smaller and smaller quarters to win the ultimate dream house. It comes from Sehwa Kim, who is creative director of quiz show <em>Scholarship Quiz.</em></p><p><em>The Quizzy Horror Show</em> follows contestants that are accused of being scaredy cats to try and turn their fear into money. Contestants who don’t blink their eyes at any heart-beating moment and can say what they saw will be winners in this spooky competition show. It comes from Jiyoon Kim, who is behind series such as <em>My Little Television</em>, which is the original version of TBS’ <em>Celebrity Show Off.</em></p><p>“We are thrilled to bring Something Special together with My Entertainment. Our talented Korean producers -Enseol Mo, Sehwa Kim, and Jiyoon Kim – look forward to collaborating with Michael and his extraordinary team at My Entertainment. They have long been a prominent industry player with their eyes on the Korean market and it is the perfect time for us to finally walk down the aisle especially when Korean creativity is being recognized more than ever,” said Jin Woo Hwang, President &amp; Executive Director, and InSoon Kim, EVP and Head of Content,</p><p>My Entertainment President and Founder Michael Yudin added, “We’re equally excited to begin working with Jin Woo and InSoon and Something Special’s great team of highly-creative producers while leveraging our personal industry relationships in the U.S. and across the globe to find homes for these shows. Coming on the heels of our successful international market collaboration with Seoul Broadcasting System (SBS) and MTV for the ultimate reality competition show, The Power, our new partnership with Something Special marks another benchmark for MY Entertainment’s strategy of expanding its activities with leaders in the Korean creative production community.”</p><p><a target="_blank" href="https://deadline.com/2021/12/korean-formats-the-quizzy-horror-show-something-special-my-entertainment-1234885947/">Original Release: DEADLINE</a></p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/korean-formats-including-the-quizzy-horror-show-head-to-u-s-after-something-special-strikes-deal-with-my-entertainment', 1639458000, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('legacy-list-with-matt-paxton-delivering-prime-time-audiences', 'Legacy List With Matt Paxton – Delivering Prime Time Audiences', 'legacy-list-with-matt-paxton-delivering-prime-time-audiences', 'As baby boomers downsize living spaces and settle estates, THE LEGACY LIST WITH MATT PAXTON helps aging homeowners catalog a lifetime of belongings, locating treasured heirlooms and unexpected valu…', '<p>As baby boomers downsize living spaces and settle estates, THE LEGACY LIST WITH MATT PAXTON helps aging homeowners catalog a lifetime of belongings, locating treasured heirlooms and unexpected valuables in the attic, closet, or even under the floorboards. Host Matt Paxton, a nine-season veteran of A&amp;E’s Hoarders, is joined by military memorabilia expert Avi Hopkins, fashion collectibles authority Jaime Ebanks, and Mike Kelleher, a walking encyclopedia of pop culture trinkets and antiques.<a target="_blank" href="https://aptonline.org/catalog/LEGACY-LIST-WITH-MATT-PAXTON"> </a></p><figure><div><img src="https://cdn.prod.website-files.com/636ec04871bc7356ad940743/636ec0f01d81f483ce45ddfb_Legacy-List-Feb-2020.jpeg" alt="Legacy List Feb 2020"></div></figure><p><a target="_blank" href="https://aptonline.org/catalog/LEGACY-LIST-WITH-MATT-PAXTON"> </a></p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/legacy-list-with-matt-paxton-delivering-prime-time-audiences', 1581915600, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('mansons-bloodline-a-real-screen-mipcom-top-pick', '"Manson''s Bloodline" A Real Screen MIPCOM Top Pick', 'mansons-bloodline-a-real-screen-mipcom-top-pick', 'MANSON’S BLOODLINE Partners: MY Entertainment for Reelz; distributed by DRG Length: 4 x 60 minutes Airing: 2019 Rights available: All rights, worldwideHow would you handle being related by blood to…', '<p><strong><em>MANSON’S BLOODLINE</em>Partners:</strong> MY Entertainment for Reelz; distributed by DRG<strong>Length:</strong> 4 x 60 minutes<strong>Airing:</strong> 2019<strong>Rights available:</strong> All rights, worldwideHow would you handle being related by blood to one of the most notorious murderers in history? It’s a very real truth for Jason Freeman, grandson of the late Charles Manson. This series provides unfiltered access to Freeman as he comes to grips with his background by attempting to better understand his grandfather.Viewers will hear phone conversations between Manson and Freeman while the former was serving out his life sentence, and see exclusive footage of Manson’s funeral. DRG commissioned and funded the series, which will make its debut on U.S. cable channel Reelz in 2019.</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/mansons-bloodline-a-real-screen-mipcom-top-pick', 1538712000, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('michael-yudin-c21-international-trade-interview', 'Michael Yudin C21 International Trade Interview', 'michael-yudin-c21-international-trade-interview', 'Michael Yudin, founder and CEO of MY Entertainment in the US, discusses the mixed ecology driving the unscripted producer’s slate and the realities of the Covid-19 lockdown. Over the years, New Yor…', '<p>Michael Yudin, founder and CEO of MY Entertainment in the US, discusses the mixed ecology driving the unscripted producer’s slate and the realities of the Covid-19 lockdown.</p><p>Over the years, New York-based MY Entertainment has built working relationships with numerous overseas producers, spanning South Korea, Scandinavia, Spain, Israel, the UK and Poland.</p><p>This isn’t the traditional route for many US producers, who, with the world’s biggest TV market in their back yard, tend to be largely focused on serving their domestic audience.</p><p>However, rights ownership for US producers still pales in comparison to those enjoyed in markets such as the UK, meaning MY Entertainment has been keen to foster international connections as a way to keep hold of more rights.</p><p>“It’s a strategy that offers international producers a route into the US market with the added bonus of allowing us to own more IP in the global market,” says founder and CEO Michael Yudin.</p><p>MY has bi-weekly calls with about a dozen international producers, during which they share key insights into what the US networks are looking for and discuss how they might collaborate to serve them, as well as fund development.</p><p>Yudin believes that as the world has become more easily connected globally, it has also become more tribal. As a result, he says it has never been more important to think globally and seek common ground.</p><p>“We producers, as cultural gatekeepers charged with creating new stories for multi-platform audiences, can help buck the divisive trend by putting aside our tribal loyalties and working more closely with one another,” he says.</p><p>Yudin points to the format Pregnant &amp; Platonic, which MY co-developed with Israel’s Gil Formats, making it an Israeli/US co-developed and co-owned original format, which aired last year on BBC2 in the UK, followed by Nelonen in Finland.</p><p>“I’m not aware of too many examples like this of independents joining forces to create unique concepts with clear global appeal and a possible route back into the US,” says Yudin.</p><p>“Reaching out in friendship brings real commercial and creative benefits and there are huge rewards for producers prepared to put in the time and spadework needed to create a two-way transatlantic street and forge trade relationships that reflect how we believe international partners should be treated.”</p><p>Of course, like every other production company in the world right now, MY Entertainment is facing up to the realities of life under lockdown, and how you keep independent businesses running during the coronavirus crisis.</p><p>Yudin is one of the lucky ones in that his company does have series in post-production, and 14 edit suites have been moved out of the company’s New York office into employees’ homes to facilitate that.</p><p>But another clutch of series are on hiatus, including the 18th season of Travel Channel’s Ghost Adventures, which was due to start shooting on March 18.</p><p>“The commissioning editors we deal with have been positive and helpful. They don’t know any more than anybody else, but if you can do something in isolation they’re open to putting it on and buying it,” he says. A one-off episode of Ghost Adventures, based in Zak Bagan’s Haunted Museum in Las Vegas, is being self-shot by the star to that end.</p><p>“They know they’re going to need product; they’re moving things around the schedule. We have a show that wasn’t due to air until later in the year that’s being moved up. In terms of timing and if they’re cutting budgets or going to buy more right now, it’s unknown,” Yudin adds.</p><p>The tipping point for companies like Yudin’s, he believes, will be if the crisis extends beyond six months. “Two months is one thing, six is quite another,” he says.</p><p>“The good news is we have contracts for 100 hours this year, and that’s without selling anything else. If this stops and we can start making them we’re going to be in great shape. If it continues, so far I haven’t had to do any lay-offs or anything like that, but at some point in time you have to do what you have to do.”</p><p>Referring to the US$2tn bailout bill passed by Congress this week, Yudin says: “My feeling is I’ll never see any of it. It’ll go to General Motors, AT&amp;T – they’ll do stock buybacks and nobody will get anything. The big issue right now, other than airlines and hotels, is people who work in the service industry. The focus is rightly on restaurants and the hospitality business. Twelve million people could be out of work there.”</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/michael-yudin-c21-international-trade-interview', 1585368000, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('mma-fighter-war-machine-gets-life-in-prison-for-brutal-attack-on-porn-star-ex-girlfriend', 'MMA Fighter Gets Life in Prison for Attack on Porn Star Ex-Girlfriend', 'mma-fighter-war-machine-gets-life-in-prison-for-brutal-attack-on-porn-star-ex-girlfriend', 'Mixed martial arts fighter War Machine has been sentenced to life in prison for the brutal beating, rape and kidnapping of his porn star ex-girlfriend in 2014.A Las Vegas jury handed down the lengt…', '<p>Mixed martial arts fighter War Machine has been sentenced to life in prison for the brutal beating, rape and kidnapping of his porn star ex-girlfriend in 2014.A Las Vegas jury handed down the lengthy sentence Monday, which will allow the 35-year-old former professional fighter to be eligible for parole after 36 years.War Machine, who legally changed his name from Jonathan Koppenhaver, was convicted on 29 of 34 charges that included first-degree kidnapping with use of a deadly weapon, sexual assault and coercing witnesses in March.“This is the kind of sentence that sometimes we don’t get on a murder case,” Clark County District Attorney Steve Wolfson tells PEOPLE. “The judge handed down what I believe is a very appropriate sentence recognizing that this guy is a trained martial artist with lots of violence in his past.”Koppenhaver initially faced 34 charges, but jurors failed to reach a verdict on two attempted-murder counts and the fighter was acquitted on three lesser counts.The attack happened in the early morning hours of August 8, 2014, when War Machine stormed into the Las Vegas home of ex-girlfriend Christy Mack and discovered her in bed with her then-boyfriend Corey Thomas.During the eight-day trial, Mack told the jury that her former beau bit Thomas in the face and right arm, then put him in a chokehold before finally allowing him to leave the house, warning him not to talk to police.Then War Machine turned his rage on Mack, beating her, she says, for two hours, during which he knocked out several teeth, broke her eye socket and nose, fractured her rib and ruptured her liver.Mack told jurors that as she lay crumpled on her bathroom floor, War Machine told her, “Now I have to kill you. I’ve gone too far. You can’t be seen like this. Everyone’s gonna know.”He expressed remorse at Monday’s hearing.“Sometimes I didn’t realize what I did until I’d already done it,” the fighter told Clark County District Court Judge Elissa Cadish, according to the Associated Press. “I hate that this happened.”Mack, whose face was nearly unrecognizable in the days following the savage beating, ended up in the hospital with 18 broken bones.“She’s a strong lady,” adds Wolfson, who appears in MY Entertainment’s Sin City Justice premiere episode on the War Machine trial that airs on June 8 at 10pm on Investigation Discovery.“I hope she’s satisfied with the justice that we delivered. But for the grace of God, he could have killed either one of them. I think they’re lucky to be alive.”During the sentencing, Mackinday told the judge that she still fears for her life.“I do know when he gets out, he will kill me,” she told the court.</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/mma-fighter-war-machine-gets-life-in-prison-for-brutal-attack-on-porn-star-ex-girlfriend', 1496721600, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('my-entertainment-goes-global-with-the-power', 'MY Entertainment Goes Global with “The Power”', 'my-entertainment-goes-global-with-the-power', 'New York-based prodco MY Entertainment has inked a new partnership with SBS Broadcasting in South Korea and Critical Density Media to develop The Power for global audiences.The new social experimen…', '<p>New York-based prodco MY Entertainment has inked a new partnership with SBS Broadcasting in South Korea and Critical Density Media to develop The Power for global audiences.The new social experiment format focuses on society’s relationship with money, class, social status and power. The Power examines how people – regardless of wealth or background – behave when given absolute power to make decisions for those around them.The Power is slated to air in Korea in early 2018, and MY Entertainment has teamed up with the Korean broadcaster to further develop the format for the U.S. and western markets.The format recently won a Gold Remi award at the Houston International Film Festival and has been nominated for a Rockie award at the Banff World Media Festival.MY Entertainment’s other copros include the series, Help! My House Is Haunted with back2back Productions and Ghost Adventures’ Zak Bagans for UKTV.A pilot has recently been created in the Netherlands for Hall Pass, the project of a partnership between MY Entertainment, London-based The Story Lab and Spain’s Phileas Productions. Working with Israel’s Gil Formats, MY Entertainment co-developed the co-parenting format Pregnant and Platonic which has now been optioned in the UK, France, Germany, Italy, Australia, Spain, Finland and Sweden.</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/my-entertainment-goes-global-with-the-power', 1497326400, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('my-entertainment-inks-deal-with-mens-health-publisher-rodale', 'MY Entertainment, Men''s Health Publisher Rodale Team Up For TV', 'my-entertainment-inks-deal-with-mens-health-publisher-rodale', 'New York-based production company MY Entertainment has won a major contract with global health and wellness content company Rodale.Rodale operates with a mission to “inspire health, healing, happin…', '<p>New York-based production company MY Entertainment has won a major contract with global health and wellness content company Rodale.Rodale operates with a mission to “inspire health, healing, happiness, and love in the world. Starting with you.” It boasts more than 100 million customers globally through an array of products and services that include magazines, books, online, mobile, e-commerce, direct-to-consumer, social, video and events. These include Men’s Health, Women’s Health, Runner’s World and Bicycling.The deal marks the first time that Rodale has engaged with a production company that can deliver traditional TV, OTT and online video content. Under its terms, MY Entertainment will work with Rodale to develop content based on Rodale’s IP and talent relationships. The MYE development team will collaborate closely with the editors of Rodale’s individual brands to identify what it considers compelling ideas and personalities for new and unique television storytelling opportunities.The partnership combines MY Entertainment’s production, development, and history of working with brands with Rodale’s portfolio of entertaining and informative content from its 100-plus global brands that are available in 67 countries reaching 100 million people. “Rodale’s portfolio is a treasure trove of factual and lifestyle entertainment” added MY Entertainment CEO Michael Yudin (pictured). “The range of lifestyle and human-interest stories is not just deep and diverse, but truly inspirational. This relationship has it all: a mine of strong IP from loved and trusted brands, and a production company with the knowledge and experience to bring them to TV.”“As a global health and wellness content company, we need to be everywhere our customers are — and TV is a natural next step,” added Rodale chief content officer Adam Campbell “This partnership will enable us to extend our brands with compelling stories that inform, entertain and provide value to both our existing consumers and new audiences around the world.”</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/my-entertainment-inks-deal-with-mens-health-publisher-rodale', 1494820800, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('my-entertainment-inks-deal-with-rodale', 'MY Entertainment Inks Deal with Men''s Health Publisher Rodale', 'my-entertainment-inks-deal-with-rodale', 'New York-based independent production company MY Entertainment is teaming up with global health and wellness content company, Rodale.Under the deal, MY Entertainment will work with Rodale to develo…', '<p>New York-based independent production company MY Entertainment is teaming up with global health and wellness content company, Rodale.Under the deal, MY Entertainment will work with Rodale to develop content based on Rodale’s IP and talent relationships. The company owns brands such as Men’s Health, Women’s Health, Runner’s World and Bicycling.The MY development team will collaborate closely with the editors of Rodale’s brand to identify compelling ideas and personalities for new storytelling opportunities.While the companies would not reveal specific examples at this stage in the deal, the stories in development will be based on real life and the titles in development will be targeted at lifestyle channels.“Rodale’s portfolio is a treasure trove of factual and lifestyle entertainment. The range of lifestyle and human-interest stories is not just deep and diverse, but truly inspirational,” said Michael Yudin, CEO of MY Entertainment, in a statement. “This relationship has it all: a mine of strong IP from loved and trusted brands, and a production company with the knowledge and experience to bring them to TV.”This deal marks the first time that Rodale has worked with a production company that can deliver traditional TV, OTT and web-based video content. Adam Campbell, chief content officer at Rodale, says television is the natural next step for the company.</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/my-entertainment-inks-deal-with-rodale', 1494475200, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('my-entertainment-inks-production-deal-with-forensic-specialist-yolanda-mcclary', 'MY Entertainment inks production deal with forensic specialist Yolanda McClary', 'my-entertainment-inks-production-deal-with-forensic-specialist-yolanda-mcclary', 'NY-based production company MY Entertainment entered into an exclusive development and production deal with forensic specialist Yolanda McClary, star of TNT unscripted true-crime series Cold Justic…', '<p>NY-based production company MY Entertainment entered into an exclusive development and production deal with forensic specialist Yolanda McClary, star of TNT unscripted true-crime series Cold Justice, and the real-life inspiration for the character of Catherine Willows in CSI. First show to come out of the deal is He’s Still Out There, focused on an unsolved 2004 murder.</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/my-entertainment-inks-production-deal-with-forensic-specialist-yolanda-mcclary', 1525233600, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('my-entertainment-inks-raft-of-development-deals', 'MY Entertainment Inks Raft of Development Deals', 'my-entertainment-inks-raft-of-development-deals', 'MY Entertainment, founded by creative leader Michael Yudin, is ringing in its 15th anniversary by inking a slate of development deals with a roster of all-star talent.The company, which recently ha…', '<p>MY Entertainment, founded by creative leader Michael Yudin, is ringing in its 15th anniversary by inking a slate of development deals with a roster of all-star talent.The company, which recently had Zak Bagans, Aaron Goodwin, Billy Tolley and Jay Wasley returning for the 16th season of Travel Channel’s <em>Ghost Adventures</em>, has signed a slew of new agreements. Yudin has confirmed development deals for Edd China (Velocity’s <em>Wheeler Dealers</em>), Matt Paxton (A&amp;E’s <em>Hoarders</em>), Yolanda McClary (TNT’s <em>Cold Justice</em>), Matt Moneymaker (Animal Planet’s<em> Finding Bigfoot</em>) and Ami James (TLC’s <em>Miami Ink</em> and <em>NY Ink</em>). MY Entertainment has also closed a behind-the-camera executive producer and development deal with Nigel Lythgoe (FOX’s <em>American Idol</em>and <em>So You Think You Can Dance</em>).Aside from the talent deals, MY Entertainment has closed co-production format deals with such partners at Newen Group (France), Vincent Television Productions (The Netherlands), Nordic World (Norway), The Story Lab (U.K.), Phileas Productions (Spain) and Gil Formats (Israel).Further, MY Entertainment has completed production on <em>Manson’s Bloodlines</em>, a four-part commission from DRG. The program will debut internationally this summer. An American version, titled <em>Charles Manson: The Funeral</em>, will bow on U.S. broadcaster REELZChannel on Saturday, April 13, at 8 p.m.Yudin said: “For 15 years, MY Entertainment has been a creative leader within the independent production community, a great business partner to every network producing in the unscripted and reality space, and a fresh collaborator and developer with our on-air talent. Right now, we have development and producing deals with dozens of partners in the U.S. and worldwide, and we are increasing the output of hours in 2019 for fans worldwide to enjoy.”“Because of the trust that our content partners have put in us to tell outstanding, emotional and thrilling stories that resonate with their audiences, MY Entertainment now has the bandwidth to strategically expand and smartly plan for more creative growth,” continued Yudin.Joe Townley, MY Entertainment COO and executive producer, added: “MY Entertainment has continued to increase our creative and production output, build relationships with production partners worldwide and been forward-thinking in adapting to and playing in the digital-native space.”Jon Sechrist, executive VP of production, development and strategy, said: “The new partnerships we have forged with well-established talent is 100 percent representative of the ambition we have in bringing the most diverse, entertaining and best expertise to air. Not only do these properties have built-in fanbases, they have a proven track record of season-over-season success.”</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/my-entertainment-inks-raft-of-development-deals', 1554696000, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('my-entertainment-international-co-development-strategy-leads-to-deals-us', 'My Entertainment International Strategy Leads to US Deals', 'my-entertainment-international-co-development-strategy-leads-to-deals-us', 'MY ENTERTAINMENT has closed a raft of funded network development, option and co-development deals with producers from Norway, France, Israel and Spain, driving forward its recently launched interna…', '<p>MY ENTERTAINMENT has closed a raft of funded network development, option and co-development deals with producers from Norway, France, Israel and Spain, driving forward its recently launched international strategy to pursue co-development of original ideas with independent producers and distributors around the globe.Funded network development deals have been signed for two European-originated shows: <em>Average</em>, optioned from DR in Denmark, is being adapted for an unnamed network; and an original format from French producer Effervescence is in development with female-skewed WE tv.MY Entertainment has closed a second option deal with DR Denmark for <em>Messing With Your Mind</em>, which won a raft of awards in Denmark when it originally aired including Best New Entertainment Format, Best Cinematography at the Danish TV Awards and Best Original TV Show at the Zulu Awards.MY Entertainment is partnering with Mission Control Media to pitch the format featuring renowned mentalist, Jan Hellesøeinto the North American market. A similar deal has been signed with Tedy Productions in Israel for <em>Séance: Live</em>,a series of live-event specials.The company has also signed deals to co-develop original ideas with Phileas Productions in Spain for <em>Hall Pass, </em>a new relationship format and with Kim Bjornqvist in Norway for <em>Brand Battles</em>, a next-generation business/competition format. Both formats are simultaneously being pitched into the US and global markets, with the first sale for <em>Brand Battles </em>already closed with Cape Town-based producer Cooked in Africa films.David Auerbach, senior vice-president of international joined MY Entertainment last summer to launch the company’s LA office and co-develop programming with international partners. Over the past six months he has forged these direct relationships with a number of European independents, with the company funding the development of original ideas for specific networks and needs, as well as identifying formats suitable for development for the US networks, which can then — with a US track-record behind them — be rolled out internationally.Michael Yudin CEO of MY Entertainment, said: “Working with this kind of creative thinking and talented individuals, with a common goal and understanding, has been nothing but great for everyone involved. When David came on board we wanted to deliver on the promise we made when we launched our international division last year — to work with the best international independents to help feed the US pipeline with successful entertainment programming. We provide our international partners with a conduit to the US networks. We supplydirection, contacts, reputation and resources; they supply great ideas.As these deals confirm, it’s not just a powerful formula and one that’s unique to MY Entertainment, butit is working.”<strong>About MY Entertainment (</strong><a href="https://myentertainment.tv/"><strong>www.myentertainment.tv</strong></a><strong>)</strong>MY Entertainment is a successful independent production company launched in 2000 by veteran TV producer and advertising executive, Michael Yudin. In addition to creating and producing compelling content, MY Entertainment has become known for pioneering new business models with advertisers, broadcasters and production companies in the US and around the world. MY Entertainment’s current series include; the 12<sup>th</sup> season of<em>Ghost Adventures</em>, for Travel Channel,<em>Las Vegas Law </em>for Investigation Discovery,<em> Baggage Battles</em> for Scripps International Networks<em>, Paranormal Museum </em>and<em> You Only Live Once </em>for Travel Channel and Sherman’s Warriors for NBC Sports Digital platform<em>. </em>With offices in NY and LA, the company currently has projects in development with Discovery, History, Travel, Lifetime, WE tv, Travel and Discovery Science.MY Entertainment is perhaps best known for the long running hit series, Pros vs. Joes.<strong>For further information on MY Entertainment, please contact</strong>:Cheryl Clarke at <strong>Mushroom Media</strong> on: Tel: +44 (0)7939554109E: cheryl@mushroom-media.co.uk</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/my-entertainment-international-co-development-strategy-leads-to-deals-us', 1457499600, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('my-entertainment-mens-health-publisher-rodale-join-forces', 'Italy, Finland Adopt Gil Parenting Format', 'my-entertainment-mens-health-publisher-rodale-join-forces', 'Gil Formats’ factual entertainment format, ‘Pregnant and Platonic’, has secured two new deals with production companies in key territories: Bulldog TV in Italy and ITV Studios in Finland. This take…', '<p>Gil Formats’ factual entertainment format, ‘Pregnant and Platonic’, has secured two new deals with production companies in key territories: Bulldog TV in Italy and ITV Studios in Finland. This takes the total number of deals for the format to eight, following on from recent deals in the UK, Australia, Germany, Spain, Sweden and France.‘Pregnant &amp; Platonic’, co-developed by Gil Formats with US based production company MY Entertainment, centres on men and women who are looking to have a child without getting romantically involved, through the process of co-parenting, and is based on Gil Formats’ CEO Assaf Gil’s personal journey to parenthood.In this format, hopeful co-parents are guided through the process by experts in co-parenting. Once they choose a partner to have a child with, the series follows the couples as they face numerous challenges and difficult decisions before they can turn their dreams of becoming parents into a reality. Each story will hopefully climax with a baby being born.The format will be distributed by Gil Formats at NATPE Budapest 2017.About Gil Formats:Gil Formats is a TV content creator and distributor, developing innovative formats for the international market including observational documentaries, semi-scripted reality comedy, game shows and reality TV. Founded in 2015, Gil Formats is based in Tel Aviv and Sister Company of veteran Israeli TV production company – Gil Productions.About MY Entertainment:MY Entertainment is a successful independent production company with a proven track record of creating cutting-edge content and pioneering new business models with broadcasters and advertisers. MY Entertainment is best known for innovative formats, great storytelling, compelling characters and high production values.The company has produced series across a wide variety of genres delivering both ratings and renewals for its partners such as: Discovery, A&amp;E, National Geographic, Lifetime, Spike, MTV, Comedy Central, Travel Channel, Investigation Discovery, Oxygen, Nickelodeon, Food Network, Animal Planet, Logo, IFC, TruTV and CMT.Based in New York with offices in Los Angeles, MY Entertainment has been at the forefront of the international business, co-producing series in Canada and the UK and forging strong relationships with independent producers around the world to co-develop original formats for the global market.Founded in 2000 by Michael Yudin, who began his career in advertising, the company is also a leader in branded entertainment, producing shows for Reebok, Jenny Craig, Schick and Stolichnya Vodka.</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/my-entertainment-mens-health-publisher-rodale-join-forces', 1496376000, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('my-entertainment-mens-health-publisher-rodale-team-up-for-tv', 'MY Entertainment, Men''s Health Publisher Rodale Join Forces', 'my-entertainment-mens-health-publisher-rodale-team-up-for-tv', 'New York-based prodco MY Entertainment has struck a deal with the magazine publisher behind Men’s Health and Runner’s World to develop lifestyle content for television around the brands.Michael Yud…', '<p>New York-based prodco MY Entertainment has struck a deal with the magazine publisher behind Men’s Health and Runner’s World to develop lifestyle content for television around the brands.Michael Yudin’s prodco has teamed up with Rodale, which publishes 100 brands across 67 countries, to work on content based on Rodale’s IP and talent relationships.Developers at MY Entertainment will collaborate with editors at Rodale’s magazines to identify ideas and personalities that would make storytelling opportunities for lifestyle series.It is the first time Rodale has engaged with a prodco that can deliver television, OTT and/or web-based video content.Adam Campbell, chief content officer at Rodale, said: “As a global health and wellness content company, we need to be everywhere our customers are – and TV is a natural next step.“This partnership will enable us to extend our brands with compelling stories that inform, entertain and provide value to both our existing consumers and new audiences around the world.”MY Entertainment CEO Yudin said: “This relationship has it all: a mine of strong IP from loved and trusted brands and a production company with the knowledge and experience to bring them to TV.”</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/my-entertainment-mens-health-publisher-rodale-team-up-for-tv', 1494820800, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('my-entertainment-preps-manson-series', 'My Entertainment Preps Manson Series', 'my-entertainment-preps-manson-series', 'My Entertainment, Michael Yudin’s US-based factual production specialist, has unveiled a crime series that centres on the grandson of mass murderer Charles Manson.The coproduction, with Zak Bagans …', '<p>My Entertainment, Michael Yudin’s US-based factual production specialist, has unveiled a crime series that centres on the grandson of mass murderer Charles Manson.The coproduction, with Zak Bagans Entertainment, follows Jason Freeman on his quest to meet his 82-year-old grandfather Manson before he dies in a Californian prison cell.The as-yet untitled show will tell the story of the convicted killer through the eyes of his grandson, whose life has been defined by his notorious relative.The show is part of a number of crime-driven projects unveiled by New York-based My Entertainment.The prodco has also been given unprecedented access to the training provided by North Las Vegas Police Department to turn raw recruits into the next generation of police officers.Training Day: North Las Vegas will introduce audiences to a cast of characters that ranges from a single mom hoping to leave her job as a bartender to an ex-Marine still scarred from several tours in Iraq.My Entertainment has also struck a development deal with Randy Sutton, a retired police lieutenant and national spokesman for the law enforcement support group Blue Lives Matter.In Behind The Badge, Sutton will travel the country interviewing cops and their families and listening to their real-life stories of bravery.Andrew Dickens13-02-2017©C21Media</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/my-entertainment-preps-manson-series', 1486962000, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('my-entertainment-signs-with-lythgoe', 'MY Entertainment Signs With Lythgoe', 'my-entertainment-signs-with-lythgoe', 'MIPTV: MY Entertainment, the New York-based prodco behind factual series including Ghost Adventures and Baggage Battles, has signed a development deal with Nigel Lythgoe (American Idol, So You Thin…', '<p>MIPTV: MY Entertainment, the New York-based prodco behind factual series including Ghost Adventures and Baggage Battles, has signed a development deal with Nigel Lythgoe (American Idol, So You Think You Can Dance).The firm, founded by Michael Yudin, is celebrating its 15th year with a raft of deals for talent in a variety of fields, led by Lythgoe.The moves follow the hiring of Jon Sechrist as executive VP of production, development and strategy from factual giant Discovery.In addition, the prodco has signed deals with a variety of talent in the fields covered by its programming, including Edd China from Velocity’s Wheeler Dealers in the motor space, Matt Paxton from A&amp;E’s Hoarders in the home genre, Yolanda McClary from TNT’s Cold Justice in true crime and Ami James from TLC’s Miami Ink and NY Ink in tattooing.The firm has coproduction format deals with partners including Newen Group (France), Vincent Television Productions (Netherlands), Nordic World (Norway), The Story Lab (UK), Phileas Productions (Spain) and Gil Formats (Israel).It recently completed production on a four-part commission from DRG, Manson’s Bloodlines, which will be shopped to the international market this summer.</p><p>An American version, Charles Manson: The Funeral, will premiere on US broadcaster Reelz on Saturday April 13.</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/my-entertainment-signs-with-lythgoe', 1554782400, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('my-entertainment-takes-format-rights-to-dancefloor-date', 'Exclusive: MY Entertainment takes format rights to "Dancefloor Date"', 'my-entertainment-takes-format-rights-to-dancefloor-date', 'New York-based prodco MY Entertainment has acquired the format rights to Dancefloor Date from Newen Distribution, the distribution arm of Newen Group.Producer, director and former dancer Nigel Lyth…', '<p>New York-based prodco MY Entertainment has acquired the format rights to <em>Dancefloor Date </em>from Newen Distribution, the distribution arm of Newen Group.Producer, director and former dancer <a target="_blank" href="http://xchange.realscreen.com/realxchange/main/profile/public/41771">Nigel Lythgoe</a> (pictured) has signed on as showrunner and executive producer of the dance competition-cum-dating series. His credits include <a target="_blank" href="http://xchange.realscreen.com/realxchange/main/projects/projectdetails/9394">So You Think You Can Dance</a>, <em>Pop Idol </em>and <a target="_blank" href="http://xchange.realscreen.com/realxchange/main/projects/projectdetails/3426">American Idol</a>.<em>Dancefloor Date</em> sees singles going on blind dates. Taking turns, they dance for their potential partner from behind a screen. All that remains visible is the dancer’s silhouette as they move. Contestants are eliminated based on nothing more than their dance moves.The format was developed by French prodco Newen. The deal was made at the MIPTV market in Cannes earlier this month.“In <em>Dancefloor Date</em>, we don’t just let them go off on a dancing date alone, we film every aspect of the date and their private emotions and invite them back to view the footage and their off the cuff remarks and participate in an honest discussion,” said Lythgoe in a statement. “That’s where my favorite part of the format begins. Did they dance beautifully around the floor like Fred and Ginger or did they tread on each other’s toes. The brutal truth comes out about a date of desire or disaster.”“This project continues our efforts in expanding our ongoing international strategy, and while we have been in the forefront of paper formats for some time, which are now coming back in fashion, we wouldn’t invest our time and expertise in something that wasn’t extremely special,” added MY Entertainment founder and CEO Michael Yudin. “<em>Dancefloor Date</em> certainly ticks that box — as does Nigel. His expertise, experience and track record in talent and dating shows is unequaled, and he also has an almost sixth sense of what will sell internationally.”</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/my-entertainment-takes-format-rights-to-dancefloor-date', 1556510400, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('my-entertainment-taps-discovery-exec-for-evp-role', 'MY Entertainment taps Discovery exec for EVP role', 'my-entertainment-taps-discovery-exec-for-evp-role', 'New York-based indie MY Entertainment has named former Discovery, Inc. executive Jon Sechrist to the newly created role of EVP of production, development and strategy. Sechrist will be tasked with …', '<p>New York-based indie MY Entertainment has named former Discovery, Inc. executive Jon Sechrist to the newly created role of EVP of production, development and strategy.</p><p>Sechrist will be tasked with developing new programming and strategy, and building on the company’s ratings successes, including Ghost Adventures, Pros Vs Joes, Breaking Borders and Baggage Battles. In addition, Sechrist will also be working on projects in the development pipeline, including tentatively titled docuseries Hidden Assets and Sin City Sober, among others.Based in New York, Sechrist will report into MY Entertainment president and founder Michael Yudin.</p><p>Previously, Sechrist has been the executive producer at TLC, vice president at Discovery Networks International and senior vice president at the Discovery-owned production house Betty.“Having worked on both the network and production side of the business, Jon is that rare executive— a TV mind understanding the pressures of production, as well as the commercial imperatives,” said Yudin in a statement. “What’s more, he knows his way around the global market, having worked extensively with U.S. and international content. That skillset, along with his background in both scripted and unscripted content, makes Jon the ideal person to lead MY Entertainment into its next phase of growth.”</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/my-entertainment-taps-discovery-exec-for-evp-role', 1528948800, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('my-entertainment-to-exercise-power', 'My Entertainment to Exercise Power', 'my-entertainment-to-exercise-power', 'US production company My Entertainment has partnered with South Korean broadcaster SBS to develop a social experiment format for international distribution.The Power is being developed by Michael Y…', '<p>US production company My Entertainment has partnered with South Korean broadcaster SBS to develop a social experiment format for international distribution.The Power is being developed by Michael Yudin’s firm with SBS and Critical Density Media and aims to spotlight society’s relationship with money, class, social status and power.SBS aired a pilot of the series in July last year and it was recently nominated for a Rockie Award at the Banff World Media Festival.The series is slated to air in South Korea in early 2018 and My Entertainment will now develop the format for the US and western markets.The format tests how people, regardless of their background or wealth, behave when granted absolute power to make decisions that affect everyone around them.David Auerbach, My Entertainment’s senior VP, said: “Our strategy to develop new formats with international partners has started to yield impressive results and we are thrilled to have the opportunity to work with a respected and successful broadcaster like SBS.“The creative collaboration to develop a very timely social experiment/format designed to work across multiple cultures has been exhilarating.”</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/my-entertainment-to-exercise-power', 1497412800, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('my-entertainment-to-launch-la-office', 'David Auerbach Joins MY Entertainment', 'my-entertainment-to-launch-la-office', 'New York producer MY Entertainment is opening an office in Los Angeles to be headed up by David Auerbach.The former Rive Gauche Television president has been appointed to the newly created role of …', '<p>New York producer MY Entertainment is opening an office in Los Angeles to be headed up by David Auerbach.The former Rive Gauche Television president has been appointed to the newly created role of senior VP of international and will focus on co-developing programming with the company’s international partners for the U.S. market.Auerbach’s credits include ABC’s The Bachelor and MTV’s America’s Best Dance Crew. Prior to joining Rive Gauche, he was a senior programming executive for Warner Bros where he developed and produced upwards of 300 hours of prime-time programming and more than 3,000 hours of cable and first-run syndication programming.“What we’re doing is very unique. We have forged strong relationships with high-quality independent international producers and have brought a senior executive on board to work with them to co-develop original concepts for the U.S. market,” said MY Entertainment CEO Michael Yudin in a statement.The company’s recent credits include Breaking Borders and Baggage Battles, and it is developing titles with Spain’s Phileas Productions and Ireland’s WAKA TV.</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/my-entertainment-to-launch-la-office', 1441684800, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('my-entertainment-video-call-center-ink-deal', 'MY Entertainment, Video Call Center Ink Deal', 'my-entertainment-video-call-center-ink-deal', 'New York-based producer My Entertainment has forged a deal to develop programmes with a US video-chat company.MY Entertainment and the Video Call Center (VCC) will co-develop formats that use the V…', '<p>New York-based producer My Entertainment has forged a deal to develop programmes with a US video-chat company.MY Entertainment and the Video Call Center (VCC) will co-develop formats that use the VCC’s video-calling and social television technologies.The two companies will also further develop some existing programmes within the VCC catalogue, which MY Entertainment will pitch for sale to networks.The VCC has already produced content for clients such as Fox TV Stations and Discovery, including workshop programmes incorporating live video calls.Joe Townley, executive producer and chief operating officer for MY Entertainment, said: “Every content provider has been trying to crack the code in developing social media-based, formatted programmes. We believe the VCC has developed the technology and the specialised production expertise to break through with that.”</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/my-entertainment-video-call-center-ink-deal', 1517547600, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('my-entertainment-wants-crime-to-pay-for-new-slate', 'MY Entertainment Wants Crime to Pay for New Slate', 'my-entertainment-wants-crime-to-pay-for-new-slate', 'As it looks to where the action is in drama, New York-based factual production specialist MY Entertainment has announced a slate of talent-driven development properties centering on crime.Heading t…', '<p>As it looks to where the action is in drama, New York-based factual production specialist MY Entertainment has announced a slate of talent-driven development properties centering on crime.Heading the new development slate is a high concept co-production with Zak Bagans Entertainment, offering a new perspective on 60’s killer and cult leader Charles Manson. The project came about after securing exclusive access to Charles Manson’s grandson, Jason Freeman, who is on a quest to meet his 82-year-old grandfather before he dies in a Californian prison cell.In another exclusive-access deal, MY Entertainment is to build on the one-hour non-fiction docu-series Las Vegas Law on Discovery ID, which offers an insight into the inner workings of the Clark County District Attorney’s office. The deal will give MY Entertainment access to the gruelling training needed to turn raw recruits into the next generation of police officers. Training Day: North Las Vegas is the real story of what recruits, their families.In a development deal with Randy Sutton, MY Entertainment will present a one-hour series that will explore not only law-enforcement agents’ personal experiences, but will also at the police’s involvement in some of the seminal cultural moments and criminal investigations in the US.Commenting on the deal, <a target="_blank" href="https://myentertainment.tv/">MY Entertainment</a> CEO Michael Yudin, said: “These deals put us front and centre of the real-life crime genre ... Zak’s retelling of the events through the eyes of his grandson will offer a genuinely new take on a tale that has lost none of its appalling fascination. Meanwhile, the development deals with the North Las Vegas Police Department and Randy Sutton are a tribute to our reputation for telling the human story, and access of US law-enforcement services with sensitivity, respect and honesty.”</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/my-entertainment-wants-crime-to-pay-for-new-slate', 1487048400, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('my-entertainment-yolanda-mcclary-pen-production-deal', 'MY Entertainment, Yolanda McClary Pen Production Deal', 'my-entertainment-yolanda-mcclary-pen-production-deal', 'Michael Yudin’s New York-based prodco MY Entertainment has penned an exclusive development and production deal with crime scene investigator Yolanda McClary. Under the deal, MY Entertainment will p…', '<p>Michael Yudin’s New York-based prodco MY Entertainment has penned an exclusive development and production deal with crime scene investigator Yolanda McClary. Under the deal, MY Entertainment will provide financial support to the development and marketing of all McClary’s television projects.The first project to emerge from the deal is the true crime series He’s Still Out There, which will examine the unsolved murder of Theresa Insana, who was strangled to death in her Las Vegas home before being dumped in a drainage area.The series will look to utilize bleeding-edge technologies, including DNA phenotyping technology, capable of creating a near exact photo of a person’s physical appearance, to bring Insana’s mysterious killer to justice 14 years later.Also in development is Crime Scene Horror Story. The series will feature McClary, who spent 26 years working as a forensic specialist for the Las Vegas Metropolitan Police Department (LVMPD), as she demonstrates her ability to read a crime scene and, by extension, a killer’s mindset and motives.McClary has worked on more than 7,000 crime scenes across her career with the LVMPD. She had previously served as a presenter over three seasons on the Dick Wolf-produced true crime series Cold Justice, which had previously aired on TNT, and has been on Oxygen since February 2017.While working as a senior crime-scene analyst, McClary served as the inspiration for Catherine Willows, the character portrayed by Marg Helgenberger on the CBS procedural forensics crime drama series CSI.“Yolanda is a proven true-crime brand, with a personality that resonates with audiences around the world,” said MY Entertainment’s Yudin in a statement. “Few people have her incredible insider knowledge of crime — and even fewer have her storytelling powers. The combination is solid gold in terms of true-crime content. With everything she does, Yolanda demonstrates her deep commitment not only to solving cases, but to giving a voice to those victims of crime who have been silenced for too long.”</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/my-entertainment-yolanda-mcclary-pen-production-deal', 1525233600, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('my-entertainment-zak-bagans-ink-development-deal', 'MY Entertainment, Zak Bagans Ink Development Deal', 'my-entertainment-zak-bagans-ink-development-deal', 'New York-based prodco MY Entertainment has penned a development deal with Zak Bagans (pictured), television host and creator of the Travel Channel series Ghost Adventures.Among the projects in deve…', '<p>New York-based prodco MY Entertainment has penned a development deal with Zak Bagans (pictured), television host and creator of the Travel Channel series Ghost Adventures.Among the projects in development between the two parties – which already work together on Ghost Adventures - is the series Pups on Parole, which follows a Las Vegas program that pairs female prisoners with dogs from an animal sanctuary. A second project in development is Flight Club, which centers on Las Vegas’s model airplane clubs, which build, fly and battle replicas of historic planes and drones.“From the minute I saw Zak’s self-financed, self-made documentary Ghost Adventures back in 2007 I knew I wanted to be in business with him,” said Michael Yudin, CEO of MY Entertainment, in a statement. “He’s not only incredibly smart but he’s also multi-talented in all aspects of successful hit programming, being as creative and charismatic behind the camera as he is on-screen.”Bagans added: “My passion for the paranormal is equal to that of television production and development. Michael and I formed a powerful relationship back in 2007 that has proven clear success through our number one-rated series and other joint ventures.“The opportunity to grow with MY Entertainment in this latest exciting phase of the company’s history and to be behind the creation of more programming in and out of the paranormal genre is hugely rewarding,” he said.</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/my-entertainment-zak-bagans-ink-development-deal', 1421989200, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('my-entertainments-mansons-bloodline-marks-first-commission-for-drg', 'MY Entertainment’s “Manson’s Bloodline” marks first commission for DRG', 'my-entertainments-mansons-bloodline-marks-first-commission-for-drg', 'British distributor DRG has fully funded New York-based production outfit MY Entertainment’s 4 x 60-minute docuseries on infamous cult leader and convicted mass murderer Charles Manson as its first…', '<p>British distributor DRG has fully funded New York-based production outfit MY Entertainment’s 4 x 60-minute docuseries on infamous cult leader and convicted mass murderer Charles Manson as its first original commission.The previously announced Manson’s Bloodline follows Jason Freeman, Manson’s grandson, on a quest to meet his 82-year-old grandfather before his death in prison on Nov. 19, 2017 in an attempt to come to terms with his past.The series also features previously unheard phone calls that Manson had with Freeman from prison; Freeman’s battle for his grandfather’s body following his death; and exclusive footage of Manson’s funeral.DRG decided to fully fund production and commission the series, without a broadcaster commitment, after working closely alongside Michael Yudin‘s MY Entertainment.</p><p>Reelz has since come aboard as broadcaster in the U.S. DRG has also sold the pan-Scandinavian rights to SVOD service Viaplay.</p><p>MY Entertainment and DRG will now look to transform Bloodline into a long-running, returning docuseries franchise that explores “how the activities and atrocities of some of the world’s most infamous criminals impacted not only their own destinies but also those of the people around them.”As a result, DRG is now developing a full slate of its own commissions.Manson’s Bloodline, meanwhile, will be delivered late summer, in advance of next year’s 50th anniversary of the Manson Family murder spree.The series is executive produced by Joe Townley at MY Entertainment and Zak Bagans of Zak Bagans Entertainment. DRG’s Richard Halliwell, Elin Thomas and Adam Barth also serve as executive producers.“Over the past year or two we have increasingly worked very closely with producers and have become integral to the development process of numerous programs – scripted and unscripted – from both a financial and content perspective,” said Halliwell, CEO of DRG, in a statement.“The traditional distribution model is no longer viable; distributors cannot sit back and wait for programming to come to them. We need to be quick, flexible and use our market knowledge – and instincts – to grab great content and ensure it moves swiftly from a paper idea into production,” Halliwell continued. “Manson’s Bloodline, with its extensive exclusive elements, was a gift of a treatment, but it also had MY Entertainment attached. We know the team there well and they have an enviable reputation for delivering great shows, so we really didn’t need to deliberate.”“DRG’s upfront development support and subsequent quick greenlight, plus the combination of our joint expertise, has produced a fascinating series that was not only able to capture key events as they happened, such as the Manson funeral, but also deliver in good time for broadcasters to schedule for 2019,” added MY Entertainment founder Michael Yudin.</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/my-entertainments-mansons-bloodline-marks-first-commission-for-drg', 1533528000, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('my-entertainments-one-foot-forward-inks-content-deals-with-mark-wahlberg-michael-sugar-alan-zweibel-more', 'My Entertainment’s One Foot Forward Inks Content Deals With Mark Wahlberg, Michael Sugar, Alan Zweibel, More', 'my-entertainments-one-foot-forward-inks-content-deals-with-mark-wahlberg-michael-sugar-alan-zweibel-more', 'EXCLUSIVE: ‍ My Entertainment ’s recently launched One Foot Forward division, formed to develop and produce premium, non-scripted content targeting the leading streaming services, has unveiled an i…', '<p><strong>EXCLUSIVE:</strong><a href="https://deadline.com/tag/my-entertainment/">‍</a></p><p><a href="https://deadline.com/tag/my-entertainment/">My Entertainment</a>’s recently launched <a href="https://deadline.com/tag/one-foot-forward/">One Foot Forward</a> division, formed to develop and produce premium, non-scripted content targeting the leading streaming services, has unveiled an impressive list of initial content deals and IP. </p><figure><div><img src="https://cdn.prod.website-files.com/636ec04871bc7356ad940743/636ec0f1154a52b7b632f00d_OFF-LOGO.jpeg" alt=""></div></figure><p>Partners include Michael Sugar’s Sugar23 (<em>Spotlight, Worth</em>), Mark Wahlberg’s Unrealistic Ideas (HBO’s <em>Wahl Street, McMillions</em>), Laurent Bouzereau (HBO’s <em>Natalie Wood: What Remains Behind,</em> Netflix’s<em> Five Came Back</em>), original Saturday Night Live writer Alan Zweibel (<em>700 Sundays, Curb Your Enthusiasm</em>, soon-to-be-released feature film <em>Here Today</em>), Jeremiah Crowell (Netflix’s<em> Pandemic: How to Prevent an Outbreak</em>, HBO Max/Alex Gibney’s Jigsaw Productions’<em> Generation Hustle</em>), Paul Pawlowski (Starz/Steven Soderbergh’s<em> Leavenworth, UFC: Road to the Octagon</em>) Emmy and Peabody Award-winner Dave Check (Starz/Steven Soderbergh’s <em>Leavenworth, ESPN 30 for 30’s Brothers in Exile</em>), and Scout Productions (4-part docuseries <em>Equal</em> for HBO Max, Emmy-winning <em>Queer Eye</em> for Netflix). The division is overseen by My Entertainment COO/Executive Producer Joe Townley.</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/my-entertainments-one-foot-forward-inks-content-deals-with-mark-wahlberg-michael-sugar-alan-zweibel-more', 1618718400, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('my-entertainments-one-foot-forward-teams-with-unrealistic-ideas-sugar23-for-premium-projects', 'MY Entertainment’s One Foot Forward teams with Unrealistic Ideas, Sugar23 for premium projects', 'my-entertainments-one-foot-forward-teams-with-unrealistic-ideas-sugar23-for-premium-projects', 'New York-headquartered MY Entertainment has unveiled several initial content deals on Tuesday (April 27) for One Foot Forward, its new producing arm for premium non-scripted content, overseen by MY…', '<p>New York-headquartered MY Entertainment has unveiled several initial content deals on Tuesday (April 27) for One Foot Forward, its new producing arm for premium non-scripted content, overseen by MY Entertainment COO and EP Joe Townley.</p><figure><div><img src="https://cdn.prod.website-files.com/636ec04871bc7356ad940743/636ec0f1154a52b7b632f00d_OFF-LOGO.jpeg" alt=""></div></figure><p>These initial partners include Academy Award winner <a target="_blank" href="https://xchange.realscreen.com/realxchange/main/profile/public/107896">Michael Sugar</a>‘s Sugar23, for <em>Pellicano</em>, a documentary film about Hollywood private investigator Anthony Pellicano.One Foot Forward will also work with Mark Wahlberg, Archie Gips and Stephen Levinson’s Unrealistic Ideas to develop <em>Milk Carton Kids</em>. This documentary series will tell the stories of children who went missing, had their photos put on milk cartons, and were eventually returned safely to their families.One Foot Forward is also teaming with Emmy-nominated filmmaker Jeremiah Crowell on <em>Russian Roulette</em>, co-produced by Xpedition. This series is about how an escort posting an Instagram photo of her billionaire client opened the door to a multi-national scandal pointing towards Russian collusion in American politics.More planned content for One Foot Forward includes <em>Comedy Docs</em>, a series of 30 for 30-style comedic documentaries, executive produced by Emmy and Tony Award-winning writer Alan Zweibel; <em>Marge Schott</em>, a documentary directed by Emmy-winning Paul Pawlowski about the first woman to own a Major League Baseball team, and the first to take a team to the World Series; and <em>Happiness Project</em>, a series with Scout Productions about Harvard University’s popular happiness-based course.“From an international scam to issues of race, political controversy and the pursuit of human happiness, these riveting, ripped from the headlines stories are driven by access to the key players involved,” said One Foot Forward head of development <a target="_blank" href="https://xchange.realscreen.com/realxchange/main/profile/public/150857">Joanna Zwickel</a>.Other announced partners that One Foot Forward will work with include Laurent Bouzerau from Netflix’s <a target="_blank" href="https://xchange.realscreen.com/realxchange/main/projects/projectdetails/10581">Five Came Back</a>, and Dave Check from ESPN 30 for 30′s <em>Brothers in Exile</em>.The production arm also announced an agreement for the exclusive multimedia rights to <em>Anything For a Hit: An A&amp;R Woman’s Story of Surviving the Music Industry</em> by Dorothy Carvello. The book is a tell-all about toxic work culture in the music business, and was critically acclaimed by <em>The New York Times</em>.</p><p>Reposted from <a target="_blank" href="https://realscreen.com/2021/04/28/my-entertainments-one-foot-forward-teams-with-unrealistic-ideas-sugar23-for-premium-projects/">Realscreen.com</a></p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/my-entertainments-one-foot-forward-teams-with-unrealistic-ideas-sugar23-for-premium-projects', 1619582400, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('my-paranormal-network-to-launch-with-13-original-podcasts-podcast-news-roundup', 'My Paranormal Network to Launch With 13 Original Podcasts (Podcast News Roundup)', 'my-paranormal-network-to-launch-with-13-original-podcasts-podcast-news-roundup', '', '', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/my-paranormal-network-to-launch-with-13-original-podcasts-podcast-news-roundup', 1626926400, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('mye-compiles-legacy-list', 'MY Entertainment compiles Legacy List', 'mye-compiles-legacy-list', 'Michael Yudin’s New York-based prodco MY Entertainment (MYE) is working on a format described as a cross between Antiques Roadshow and History Detectives for the American syndication market, with K…', '<p>Michael Yudin’s New York-based prodco MY Entertainment (MYE) is working on a format described as a cross between Antiques Roadshow and History Detectives for the American syndication market, with Kew Media distributing globally.Legacy List With Matt Paxton has been commissioned by PBS member station VPM in Richmond Virginia. The show will be produced in partnership with Shipyard Entertainment and distributed by American Public Television (APT) to more than 80% of the US market via more than 270 public-television stations.It will also be shopped internationally as a format, with MYE agreeing a deal that will see Kew Media Distribution handle international sales.Based on an original format concept by MYE entitled Hidden Assets, Legacy List With Matt Paxton turns on the premise that the most important museum in the world may well be in your parents’ basement, attic, closet – or even under their floorboards.The 6×60’ series combines non-fiction storytelling with public-television sensibilities to explore histories and hidden treasures that come to light when clearing out family homes.The show’s host is Matt Paxton, who is moving to public television after nine seasons fronting hit show Hoarders for cablenet A&amp;E. A team of expert collectors and advisors will join Paxton in the show.Now in production, the programme is slated to air on public television nationwide in early 2020.</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/mye-compiles-legacy-list', 1564718400, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('mye-partners-with-nbcus-wilshire-studios-for-mvteen', 'Reelz To Air DRG-Funded Charles Manson Documentary Series ‘Manson’s Bloodline’', 'mye-partners-with-nbcus-wilshire-studios-for-mvteen', 'Manson’s Bloodline is a four-part series that will tell the story of Charles Manson’s grandson, Jason Freeman, and how he came to terms with his notorious grandfather’s murder spree. It comes in ad…', '<p>Manson’s Bloodline is a four-part series that will tell the story of Charles Manson’s grandson, Jason Freeman, and how he came to terms with his notorious grandfather’s murder spree. It comes in advance of next year’s 50th anniversary of the killings.The series, which will be delivered in late summer, will be produced by Breaking Borders producer My Entertainment, which obtained access and secured previously unheard telephone calls that Manson had with Jason from prison. It will also follow Jason’s battle for his grandfather’s body following his death in November 2017 and exclusive footage of Manson’s funeral from earlier this year.It will air on the Autopsy broadcaster in the U.S. and Viaplay across Scandinavia. DRG fully funded production and commissioned the show without a broadcaster commitment before securing broadcaster deals.It comes as the Manson story is set to dominate screens over the next twelve months. Quentin Tarantino is working on a Manson feature that will star Leonardo DiCaprio and Margot Robbie, while Deadline revealed in June that Fox is exploring the gruesome murders in a Liev Schreiber-narrated documentary special based on a vault of unseen footage of the cult.My Entertainment and DRG also hope that Bloodline will become a long-running, returning documentary series franchise, exploring how the activities and atrocities of some of the world’s most infamous criminals impacted not only their own destinies but also those of the people around them.Manson’s Bloodline is executive produced by Joe Townley, Zak Bagans, Richard Halliwell, Elin Thomas and Adam Barth.DRG CEO Halliwell said, “Over the past year or two we have increasingly worked very closely with producers and have become integral to the development process of numerous programmes – scripted and unscripted – from both a financial and content perspective. With our business constantly evolving a full commission was a natural next step and we are delighted that our first greenlight is the high-profile story told in Manson’s Bloodline.Halliwell continues: “The traditional distribution model is no longer viable; distributors cannot sit back and wait for programming to come to them. We need to be quick, flexible and use our market knowledge – and instincts – to grab great content and ensure it moves swiftly from a paper idea into production. Manson’s Bloodline, with its extensive exclusive elements, was a gift of a treatment, but it also had My Entertainment attached. We know the team there well and they have an enviable reputation for delivering great shows, so we really didn’t need to deliberate. This has been a very positive development for DRG and we are now pursuing a full slate of our own commissions.”Michael Yudin, founder of My Entertainment added, “As well as our track-record for creating cutting-edge content, such as Pros Vs. Joes and Breaking Borders, we are known for pioneering new business models and co-developing projects with international partners. However, this is the first time we have been directly commissioned by a company best known as a distributor. DRG’s upfront development support and subsequent quick greenlight, plus the combination of our joint expertise, has produced a fascinating series that was not only able to capture key events as they happened, such as the Manson funeral, but also deliver in good time for broadcasters to schedule for 2019”.</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/mye-partners-with-nbcus-wilshire-studios-for-mvteen', 1533528000, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('names-in-the-news', 'MY Entertainment Teams Up With NBA Star Tyson Chandler', 'names-in-the-news', 'OUTSIDE THE LINES: MY Entertainment is teaming up with Phoenix Suns Center TYSON CHANDLER to develop a new reality TV series taking viewers behind-the-scenes into the world of fashion in sports. Ch…', '<p>OUTSIDE THE LINES: MY Entertainment is teaming up with Phoenix Suns Center TYSON CHANDLER to develop a new reality TV series taking viewers behind-the-scenes into the world of fashion in sports. Chandler will serve as an executive producer and make appearances on the show, which will focus on his design stylist and fashion consultant, BROWNE ANDREWS (THE DAILY)</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/names-in-the-news', 1491883200, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('nbc-sports-to-launch-first-original-digital-series', 'NBC Sports to Launch First Original Digital Series with MY Entertainment', 'nbc-sports-to-launch-first-original-digital-series', 'NBC Sports plans to launch about a half-dozen original series produced for digital platforms in the next year, with the group’s first entry slated to take the field next week.The NBC Sports Digital…', '<p>NBC Sports plans to launch about a half-dozen original series produced for digital platforms in the next year, with the group’s first entry slated to take the field next week.The NBC Sports Digital Shorts initiative will encompass different categories, including special packages of highlights and exclusive interviews. The first project is “Sherman’s Warriors,” a six-part docu-series following former Green Bay Packers head coach Mike Sherman as he coaches the Nauset Warriors, a high school football team in Cape Cod, Mass.“Sherman’s Warriors” (pictured above) will debut Sunday, Oct. 18, immediately following NBC’s “Sunday Night Football” telecast of the New England Patriots and Indianapolis Colts game, with new episodes to be released on subsequent Sundays. Each episode runs 6-8 minutes, accompanied by 1-2 minute behind-the-scenes clips.NBC Sports’ free, ad-supported shorts will be produced both in-house and by external production companies. “Sherman’s Warriors” is produced by MY Entertainment and Matching Baggage Prods., overseen by NBC Sports Group’s Ron Wechsler, senior VP of original programming and development, and Michael Kane, senior director of original programming and development.Brian Gilmore, senior director of video for NBCSports.com, is heading up the original shorts initiative. “In furthering NBC Sports Group’s commitment to storytelling and NBCSports.com’s focus on video, NBC Sports Digital Shorts will help us provide users with more compelling, digital-focused content than ever before,” he said.“Sherman’s Warriors” will be available at NBCSports.com/ShermansWarriors and other NBC Sports Digital platforms for desktops, tablets, mobile devices and connected TVs. In addition, the series and future digital shorts will be distributed via partners including Yahoo and Comcast’s new Watchable short-form video service.</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/nbc-sports-to-launch-first-original-digital-series', 1444795200, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('nevada-high-court-oks-tv-shows-courtroom-cameras', 'Nevada High Court OKs Reality TV Show’s Courtroom Cameras', 'nevada-high-court-oks-tv-shows-courtroom-cameras', 'CARSON CITY, Nev. (CN) – News cameras have been allowed in state courtrooms in Nevada for years. But whether that open-door policy extends to a cable television show that focuses on Las Vegas prose…', '<p>CARSON CITY, Nev. (CN) – News cameras have been allowed in state courtrooms in Nevada for years. But whether that open-door policy extends to a cable television show that focuses on Las Vegas prosecutors became its own legal drama, with the state’s high court providing the concluding scene.It was not a nail-biter of an ending, however, as the Nevada Supreme Court ruled unanimously that My Entertainment TV, which filmed portions of a murder trial for the cable television show “Las Vegas Law,“ &nbsp;is allowed to record courtroom proceedings as a “news reporter” under the court’s rules for cameras in the court.In a 12-page <a href="http://www.courthousenews.com/wp-content/uploads/2017/04/Las-Vegas-Law-Nevada-SC-OPINION.pdf">opinion</a> released Thursday, the court concluded that footage for the show, which airs on the Investigation Discovery channel, is shown for educational or informational purposes – a key element for allowing electronic coverage of state court proceedings.“Las Vegas Law” premiered in May 2016 and follows Clark County District Attorney Steve Wolfson and his team of prosecutors in the Las Vegas metropolitan area as they work cases. The show was renewed for a second season this year with six episodes scheduled, according to Investigation Discovery.The defendant in the murder trial, Michael Solid, challenged the trial judge’s decision to allow filming for the show. He argued in part that My Entertainment TV is not a news reporter and that the footage would not be used solely for educational or informational purposes but also for unrelated advertising reasons, which is not allowed.The court, however, dismissed the advertising argument. Any footage used in creating the show would be used for a “related” advertising purpose, the opinion states.Even though Solid’s trial and the filming have ended, the court determined the matter is not moot because “remaining shows on the current production contract, as well as episodes of any future seasons, will present many of the same issues of widespread importance.”The court further said Solid’s petition “presents a novel, important issue of law in need of this court’s clarification.”The decision, written by Justice Mark Gibbons, cited the court’s definition of a “news reporter” within its media-coverage rules. Under that plain language, My Entertainment TV meets the definition, the court said, turning aside another of Solid’s arguments that the television producer’s stated purpose is to create a “docu-drama” as opposed to a traditional news program.The show’s footage “concerns local events (trials within the community) for dissemination to the public,” Gibbons wrote.Gibbons rejected another argument that the show’s producer is not a news reporter because Clark County receives royalties and has some editorial control over the show.“While this is perhaps an uncommon arrangement in the news business it does not run afoul of any requirement” of the rule defining a news reporter, Gibbons wrote.The court also found that Solid failed to overcome the presumption of allowing electronic recording in the courtroom with his contention that filming would jeopardize his right to a fair trial primarily because his attorneys would be distracted by the cameras.Gibbons wrote: “Solid did not present evidence showing how the (television producer’s) cameras affected the fairness of the trial, the dignity of the proceedings, or the ability of trial counsel to present effective advocacy any differently than the other cameras in the courtroom.”The court also concluded that an agreement between the show’s producer and Clark County did not require special public defenders in the trial to consent to the filming. Part of that agreement provides that filming of county employees will be conducted only with each employee’s written permission.Those consent requirements only apply to filming in the district attorney’s office, the court ruled.</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/nevada-high-court-oks-tv-shows-courtroom-cameras', 1493352000, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('north-las-vegas-police-recruits-to-star-in-pilot-for-reality-show', 'North Las Vegas Police Recruits to Star in Reality Show', 'north-las-vegas-police-recruits-to-star-in-pilot-for-reality-show', 'The fresh-faced recruits joining the North Las Vegas Police Department could soon be thrust into the national spotlight. The production company in charge of the reality programs “Las Vegas Law” and…', '<p>The fresh-faced recruits joining the North Las Vegas Police Department could soon be thrust into the national spotlight. The production company in charge of the reality programs “Las Vegas Law” and “Ghost Adventures” is turning its attention to a show that will follow North Las Vegas’ newest cops through training exercises and interactions with residents.“I was thinking about what’s going on in the country right now with police departments and their communities, and I came up with an idea that will help people understand what really happens during training and why these men and women choose to get into this profession,” said Michael Yudin, president of MY Entertainment in New York.“The people I work with suggested that I focus on North Las Vegas because there’s been some recent success with new housing and industrial businesses moving in, but the city has a long way to go,” Yudin said. “I think they have a great story to tell, and we want to help tell it.”MY Entertainment will shoot a pilot later this month for the new reality show, tentatively titled, “Field Training Officer, North Las Vegas,” under a deal unanimously approved Wednesday night by the City Council.Once the pilot is shot, Yudin and executive producer Wayne Root will shop the concept to television networks. If the series is picked up, then North Las Vegas stands to earn $4,000 per 30-minute episode and up to $6,000 for an hourlong show.This won’t be the first cop show making reference to North Las Vegas. “Nasty Boys,” a scripted crime drama, ran for a brief 13 episodes in 1990, based on narcotics officers in the North Las Vegas Police Department. The department’s officers also have been featured in episodes of the “COPS” reality show.North Las Vegas has 17 rookies undergoing training, police spokeswoman Ann Cavaricci said. Yudin probably will follow the new recruits through the classroom lessons that are shared with other local law enforcement agencies, lasting 22 weeks at the Southern Desert Regional Police Academy at the College of Southern Nevada’s campus in Henderson.After that, recruits attend an internal “advanced academy” for five weeks at North Las Vegas City Hall, where they learn about the department’s policies. From, there, the rookies spend up to six weeks of training in the field with a supervisor.Police Chief Alex Perez has signaled “strong support” for the television show and its potential to inspire youths to join his department, Cavaricci said.“He hopes that sharing that process will provide insight into what it takes to train a fresh recruit and mold them into a top-rate police officer,” Cavaricci said. “This show is an opportunity for the public to see the excellent level of training our officers get and the focus we have on community engagement as a means of assisting our citizens.”</p><p>Contact Art Marroquin at amarroquin@reviewjournal.com or 702-383-0336. Find @AMarroquin_LV on Twitter.</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/north-las-vegas-police-recruits-to-star-in-pilot-for-reality-show', 1471406400, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('on-halloween-night-travel-channel-presents-a-terrifying-four-hour-live-ghost-adventures-investigation-inside-zak-bagans-haunted-museum-live-event-airs-wednesday-october-31-at-8-p-m-et-5-p', 'On Halloween Night, Travel Channel Presents A Terrifying Four-Hour Live ''Ghost Adventures''', 'on-halloween-night-travel-channel-presents-a-terrifying-four-hour-live-ghost-adventures-investigation-inside-zak-bagans-haunted-museum-live-event-airs-wednesday-october-31-at-8-p-m-et-5-p', 'On Halloween Night, Travel Channel Presents A Terrifying Four-Hour Live ''Ghost Adventures'' Investigation Inside Zak Bagans'' Haunted Museum - Live Event Airs Wednesday, October 31 at 8 P.M. ET / 5 P…', '<p><strong>On Halloween Night, Travel Channel Presents A Terrifying Four-Hour Live ''Ghost Adventures'' Investigation Inside Zak Bagans'' Haunted Museum - Live Event Airs Wednesday, October 31 at 8 P.M. ET / 5 P.M. PT.</strong></p><p><strong>‍</strong>Bagans Will Attempt to Open the Most Haunted Object Known to Exist: The Dybbuk Box.The Frights Continue When an All-New Season of the Hit Series Premieres Saturday, November 3 at 9 p.m. ET/PT.</p><p>‍<strong>NEW YORK </strong>(<strong>October 5, 2018</strong>) – Be afraid. Be very afraid. For 10 years, “Ghost Adventures” has brought chilling ghost investigations into viewers’ homes, creating unforgettable paranormal experiences for those brave enough to watch. In celebration of the scariest night of the year, Travel Channel has lined up a ghostly event to die for – <strong>“Ghost Adventures Live”</strong>premieres <strong>Wednesday, October 31 beginning at 8 p.m. ET/5 p.m. PT</strong>.</p><p>On the one-year anniversary of the museum’s opening, the “Ghost Adventures” team – Zak Bagans, Aaron Goodwin, Jay Wasley and Billy Tolley – will lock down inside Bagans’ Las Vegas Haunted Museum in a special four-hour live Halloween investigation, hosted by special guest Josh Gates of “Expedition Unknown.” The team will investigate the 33-room historic mansion brimming with hauntings from its own dark past – and that now houses thousands of haunted objects, some so frightening and powerful they can’t even be touched, including Peggy the Doll who is known to cause heart attacks and the infamous Dybbuk Box, believed to be haunted by a malicious spirit.Sealing themselves inside to face these extreme supernatural forces head on, and using the most advanced technology and equipment, the “Ghost Adventures” team will push themselves further than they’ve ever gone before. Over 30 cameras will capture the event live, while host Josh Gates will liaise between the dedicated nerve center and evidence review area positioned on site. In an unprecedented move, Bagans will attempt to open the Dybbuk Box, quite possibly evoking paranormal mayhem.Anything can happen, and an exorcist and ambulance will be on location just in case. With the help of special guests and experts – including Dave Schrader, Lady Snake, Chris Fleming, Michael and Marti Parry, Bill Chappell and others – it’s sure to go down as one of the most terrifying nights in paranormal history!“I’m excited for fans to join us on this special LIVE investigation at my Haunted Museum, which has its own sinister history. Many dark rituals took place at the house in the 1970s, and the residual effects can still be felt,” said Bagans. “After 10 years, our passion and enthusiasm for investigating the paranormal is only growing more powerful the more we develop our connections with every spirit and location we visit. So get ready for an unforgettable Halloween and some more incredible new episodes of ‘Ghost Adventures!’”Through an on-location live video stream, viewers can monitor all of the “Ghost Adventures Live” activity on Travel Channel’s <a href="https://www.facebook.com/TravelChannel">Facebook </a>Live platform and comment on any findings in real time, using #GhostAdventuresLive. Comments will feed directly to Travel Channel’s Social Command Center, monitored by digital host Andrew “GUNNAROLLA” Gunadie, who will share with Josh Gates and the “Ghost Adventures Live” team.The frights don’t end on Halloween. An <strong>all-new season </strong>of “Ghost Adventures” returns on <strong>Saturday, November 3 at 9 p.m. ET/PT,</strong> as the team travels to St. Anthony, Idaho, to investigate a former school with a dark history of death. Children were sent to the Idaho State Reform School with the hope of being reformed, but the result was often the opposite. The former girl’s dormitory and infirmary were eventually transformed into homes where a family now lives in distress – plagued by intense unseen forces and violent attacks. As the team begins their lockdown, they document unnerving evidence of unexplained activity, disembodied voices and their own physical attacks.Beginning Saturday, November 3, and running through December 22, fans can enter Travel Channel’s “Ghost Adventures Giveaway” each week for the chance to win a weekly prize pack with “Ghost Adventures” goodies or a gift card, and all weekly entries will be entered into the grand prize drawing – a trip for two to Zak Bagans’ Las Vegas Haunted Museum. A code will be revealed Saturday nights during each new “Ghost Adventures” episode at 9 p.m. ET/PT; viewers can then enter that code online for the chance to win. Check out “Ghost Adventures” on <a href="https://www.travelchannel.com/shows/ghost-adventures">TravelChannel.com </a>for more, including special show extras, behind-the-scenes photos and exclusive videos. Follow @TravelChannel, @GhostAdventures and #GhostAdventures on <a href="https://www.facebook.com/TravelChannel/">Facebook</a>, <a href="https://na01.safelinks.protection.outlook.com/?url=https%3A%2F%2Ftwitter.com%2Ftravelchannel&amp;data=02%7C01%7Ckrivezzi%40travelchannel.com%7C8eb71201bfb74960875d08d5427c6b30%7Cf19252c6689a4a999966b37335364213%7C0%7C0%7C636488024586975673&amp;sdata=oJ2U8BUzKm3j8ssxUoNm2YhQEWY%2BjWmXsqc6hO8NOmE%3D&amp;reserved=0">Twitter</a>, <a href="https://na01.safelinks.protection.outlook.com/?url=https%3A%2F%2Fwww.instagram.com%2Ftravelchannel%2F&amp;data=02%7C01%7Ckrivezzi%40travelchannel.com%7C8eb71201bfb74960875d08d5427c6b30%7Cf19252c6689a4a999966b37335364213%7C0%7C0%7C636488024586975673&amp;sdata=Nvm4h0KBR%2Fw5IGIVg2hQwE8c5df%2BniAJcrtwZc80cfk%3D&amp;reserved=0">Instagram </a>for additional content and updates. Follow the team on Twitter: <a href="https://twitter.com/Zak_Bagans">@Zak_Bagans</a>, <a href="https://twitter.com/AaronGoodwin">@AaronGoodwin, </a><a href="https://twitter.com/BillyTolley">@BillyTolley</a>, <a href="https://twitter.com/jaywasley">@jaywasley</a>Plus, tune into a special four-part “Ghost Adventures” miniseries – <strong>“Graveyard of the Pacific”</strong> – beginning <strong>Saturday, October 6 at 9 p.m. ET/PT.</strong> The team investigates this treacherous nautical region of the Pacific Northwest, where darkness plagues both land and sea and haunted locations flood the area.“Ghost Adventures” is produced by MY Entertainment for Travel Channel. For MY Entertainment, the executive producers are Michael Yudin and Joe Townley. Zak Bagans also serves as an executive producer on the series. For Travel Channel, the executive producer is Daniel A. Schwartz, Jane Latman is general manager and Henry Schleiff is group president of Investigation Discovery, Travel Channel, American Heroes Channel and Destination America.</p><p>‍<strong>ABOUT TRAVEL CHANNEL</strong></p><p><strong>‍</strong>For the bold, daring and spontaneous; those adventurers who embrace the thrill of the unexpected; those risk-takers who aren’t afraid of a little mystery; if you’re up for anything, down for whatever, and above all, love great stories, journey on to Travel Channel. We’re more than you expect and everything you didn’t know you were looking for. Reaching more than 82 million U.S. cable homes, Travel Channel is the world’s leading travel media brand.Fans also can visit <a href="http://www.travelchannel.com/">Travel Channel</a> for more information or interact with other fans through <a href="https://www.facebook.com/TravelChannel">Facebook</a>, <a href="https://twitter.com/travelchannel">Twitter</a>, <a href="https://www.pinterest.com/travelchannel/">Pinterest</a> and <a href="https://www.instagram.com/travelchannel/">Instagram</a>. Travel Channel is owned by Discovery, Inc., a global leader in real life entertainment whose portfolio also includes Discovery Channel, HGTV, Food Network, TLC, Investigation Discovery and OWN: Oprah Winfrey Network.</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/on-halloween-night-travel-channel-presents-a-terrifying-four-hour-live-ghost-adventures-investigation-inside-zak-bagans-haunted-museum-live-event-airs-wednesday-october-31-at-8-p-m-et-5-p', 1539230400, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('on-the-air', 'MY Entertainment Teams With NBA All-Star Tyson Chandler', 'on-the-air', 'MY Entertainment signed on NBA All-Star Tyson Chandler to develop a new reality television series that examines the world of fashion in sports. Chandler will serve as an executive producer and make…', '<p><strong>MY Entertainment</strong> signed on NBA All-Star <strong>Tyson Chandler</strong> to develop a new reality television series that examines the world of fashion in sports. Chandler will serve as an executive producer and make appearances on the show, which will focus on his design stylist and fashion consultant, Browne Andrews. “Fashion has become an outlet for me and a lot of other athletes to creatively and stylishly convey our personalities off the court,” said Chandler. “Browne has been instrumental in helping me find my personal style and I am excited to partner with MY Entertainment to give people an inside look at what it takes to be a top stylist dressing some of the most stylish NBA players.”</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/on-the-air', 1491883200, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('one-foot-forward-unveils-unscripted-slate', 'One Foot Forward Unveils Unscripted Slate', 'one-foot-forward-unveils-unscripted-slate', 'New York-based One Foot Forward, the premium content division of Michael Yudin’s MY Entertainment, has linked up with a number of partners on new non-scripted content aimed at streamers. One Foot F…', '<p>New York-based One Foot Forward, the premium content division of Michael Yudin’s MY Entertainment, has linked up with a number of partners on new non-scripted content aimed at streamers.</p><figure><div><img src="https://cdn.prod.website-files.com/636ec04871bc7356ad940743/636ec0f1154a52b7b632f00d_OFF-LOGO.jpeg" alt=""></div></figure><p>One Foot Forward is working with partners including Academy Award-winner Michael Sugar’s Sugar23 (Spotlight); Mark Wahlberg, Archie Gips and Stephen Levinson’s Unrealistic Ideas; Laurent Bouzereau; and original Saturday Night Live writer Alan Zweibel.It is also developing projects with Jeremiah Crowell, Paul Pawlowski, Emmy- and Peabody Award-winner Dave Check and Scout Productions.The division, overseen by MY Entertainment chief operating officer and executive producer Joe Townley, has also inked a deal for exclusive rights to Dorothy Carvello’s tell-all music industry book Anything for a Hit: An A&amp;R Woman’s Story of Surviving the Music Industry.One Foot Forward has joined Sugar23 and Bouzereau, who will direct, to develop Pellicano, the behind-the-headlines real-life story of Hollywood’s most sought-after private investigator, Anthony Pellicano.With Wahlberg and Unrealistic Ideas, the unit is developing Milk Carton Kids, a documentary series featuring the stories of four missing kids who were reunited with their families after their images were displayed on milk cartons in the 1980s.One Foot Forward head of development Joanna Zwickel said: “From an international scam to issues of race, political controversy and the pursuit of human happiness, these riveting, ripped-from-the-headlines stories are driven by access to the key players involved. One Foot Forward is thrilled to be in business with such top-tier talent and eager to bring their unique points of view to the marketplace.”</p><p>Reposted from original article from <a target="_blank" href="https://www.c21media.net/news/one-foot-forward-unveils-unscripted-slate/">C21 Media</a></p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/one-foot-forward-unveils-unscripted-slate', 1618804800, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('oxygen-greenlights-5-new-true-crime-series', 'Oxygen Greenlights 5 New True-Crime Series', 'oxygen-greenlights-5-new-true-crime-series', 'Oxygen Media is continuing to expand its killer slate by greenlighting five new series, as well as a documentary about Kim Kardashian’s campaign for criminal justice reform.The new set of projects …', '<p>Oxygen Media is continuing to expand its killer slate by greenlighting five new series, as well as a documentary about Kim Kardashian’s campaign for criminal justice reform.The new set of projects hail from an eclectic range of creatives, including Kardashian, Mark Wahlberg, Ice-T, and Jason Blum.“Oxygen is tremendously excited to work with some of the biggest names in the industry on such important projects,” said Rod Aissa, executive vice president of original programming and development for Oxygen. “This year we’ve increased our original hours by more than 30%, and we’ll keep ramping up our programming efforts as more fans flock to the network to experience best in class content.”In 2017, Oxygen rebranded to become a fulltime true-crime destination. Some of its biggest hits include “Aaron Hernandez Uncovered,” “Unspeakable Crime: The Killing of Jessica Chambers” and “Cold Justice” from executive producer Dick Wolf.<strong>Greenlights“The Jane Doe Murders” </strong>(Working Title)Produced by MY Entertainment with Michael Yudin serving as the executive producer.In the US alone, there are nearly 40,000 open cases where a victim of a violent crime remains unidentified – bodies without names and loved ones never returned to their families. But now thanks to ground-breaking new forensic technology, investigators are able to bring a victim’s face to life and uncover new evidence. In each episode of “The Jane Doe Murders,” renowned crime scene investigator, Yolanda McClary, will work on a different unknown victim case until their identity is revealed. She will then present her findings to local authorities and work alongside them to catch the perpetrator.</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/oxygen-greenlights-5-new-true-crime-series', 1557374400, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('pbs-orders-legacy-list', 'Exclusive: PBS, Virginia Public Media order hidden treasure series from MYE', 'pbs-orders-legacy-list', 'Michael Yudin’s New York-based prodco MY Entertainment (MYE) has been commissioned to produce Legacy List with Matt Paxton for Virginia Public Media and PBS member station WCVE.The show — described…', '<p>Michael Yudin’s New York-based prodco MY Entertainment (MYE) has been commissioned to produce <em>Legacy List with Matt Paxton</em> for Virginia Public Media and PBS member station WCVE.The show — described in a release as “Antiques Roadshow meets History Detectives” — will see a team of expert collectors and advisers, including Mike Kelleher, walking viewers through the sometimes priceless items that can be found in your parents’ basement, attic, closet or even under their floorboards.<em>Legacy List</em> will be produced in partnership with Shipyard Entertainment and distributed by American Public Television (APT) to over 80% of the U.S. TV market via over 270 public-television stations.Matt Paxton serves as host after nine seasons fronting A&amp;E’s hit format Hoarders.“MYE continues to look for new business models and relationships to help it succeed in the new-media environment — and we’ve found the perfect partner in WCVE, which not only has a clear vision of the future of public broadcasting, but is well on the way to realizing it,” said MYE founder and CEO Yudin in a statement.“As one of the few U.S. producers that’s as embedded in the international market as we are in our home territory, all our instincts tell us that <em>Legacy List with Matt Paxton</em> has the makings of a worldwide hit. While public television is naturally focused on serving American audiences, these human stories of love, loss and remembrance transcend local boundaries. It doesn’t matter if you’re in Virginia or Vienna, there’s nothing more precious than family treasure.”Added WCVE chief content officer Steve Humble: “This was a rare opportunity to pair a nationally known, home-grown TV talent like Matt Paxton with a story-rich format that’s absolutely right for our audiences, helmed by a skilled, seasoned and patient partner like MYE. We couldn’t pass it up. This project is one of several that signals a new era in our organization’s role in public media.”The series is currently in production and set to premiere in early 2020</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/pbs-orders-legacy-list', 1564459200, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('pools-with-a-view-to-air-on-travel-channel-june-4th', 'Pools With a View Set to Air on Travel Channel June 4th', 'pools-with-a-view-to-air-on-travel-channel-june-4th', 'Splash! Travel Channel’s “Dive In” summer lineup of water-themed programming starts Sunday, June 4th at 11pm with the premiere of the new special Pools With a View produced by MY Entertainment.', '<p>Splash! Travel Channel’s “Dive In” summer lineup of water-themed programming starts Sunday, June 4th at 11pm with the premiere of the new special <strong>Pools With a View </strong>produced by MY Entertainment.</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/pools-with-a-view-to-air-on-travel-channel-june-4th', 1493697600, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('pregnant-and-platonic-goes-to-finland', 'Pregnant and Platonic Goes To Finland', 'pregnant-and-platonic-goes-to-finland', 'Finnish commercial TV channel Nelonen has ordered 10 episodes of the factual entertainment format Pregnant &amp; Platonic, which looks at a new way to enter into parenthood.ITV Studios in Finland w…', '<p>Finnish commercial TV channel Nelonen has ordered 10 episodes of the factual entertainment format Pregnant &amp; Platonic, which looks at a new way to enter into parenthood.ITV Studios in Finland will produce the series, currently in production, with an airdate set for 2019.The format, co-developed by Gil Formats and MY Entertainment, centers on people who want to have a child without being romantically involved. The series follows the meeting of potential co-parenting partners over a year, as they face challenges and difficult decisions before the baby is born. It is based on Gil Formats’ CEO, Assaf Gil‘s personal journey to parenthood.</p><p>Nelonen is the second broadcaster to commission the format, with a UK version set to premiere on BBC2 in 2019.</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/pregnant-and-platonic-goes-to-finland', 1527134400, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('reality-tv-trade-group-nearly-triples-membership', 'MY Entertainment Joins Non-Fiction Producers Association', 'reality-tv-trade-group-nearly-triples-membership', 'The newly formed Non-Fiction Producers Association has added 14 member-companies to its fold, bringing its total membership to 22. The new recruits are Bunim-Murray Productions, Evolution Media, Ey…', '<p>The newly formed Non-Fiction Producers Association has added 14 member-companies to its fold, bringing its total membership to 22. The new recruits are Bunim-Murray Productions, Evolution Media, Eyeworks USA, Go Go Luckey Entertainment, GRB Entertainment, High Noon Entertainment, Lighthearted Entertainment, LMNO Productions, MY Entertainment, Optomen, Renegade 83, Sharp Entertainment, The Ebersol Lanigan Company, and Zodiak New York.“We are gratified by the continuing and growing positive response to the formation of the NPA and are delighted to welcome these new companies – from the East and West coasts – to our ranks,” said executive director Rick Feldman. “The NPA now includes 22 of the industry’s top television producers, and we are currently in talks with more production companies that have expressed serious interest.”The NPA also announced that it has formed a six-member Executive Committee and a 15-member Board of Directors, whose inaugural meeting will be held September 10 in New York, where the group will establish its first set of initiatives.Headquartered in New York City, the NPA was formed in July with charter members Atlas Media Corp., Big Fish Entertainment, Jane Street Entertainment, Leftfield Pictures, Loud TV, Magilla Entertainment, Original Media, and True Entertainment. It was created as a professional body to provide industry information, training and assistance to production companies, their staffs, and production employees, and to “promote ‘best practices’ that ensure production employees, independent contractors, vendors and other stakeholders have a voice and platform for meaningful discourse that can encourage and contribute to the continued success and welfare of all parties within the nonfiction television industry.”</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/reality-tv-trade-group-nearly-triples-membership', 1409112000, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('renewed-and-returning-city-bakes-las-vegas-law', 'Renewed and Returning: “Las Vegas Law”', 'renewed-and-returning-city-bakes-las-vegas-law', 'This week’s round-up of programs with new seasons on the way includes series from Investigation Discovery, HGTV, and Food Network UK.Investigation Discovery has greenlit a second season of Las Vega…', '<p>This week’s round-up of programs with new seasons on the way includes series from Investigation Discovery, HGTV, and Food Network UK.Investigation Discovery has greenlit a second season of Las Vegas Law, slated for 2017. The series features Clark County District Attorney Steve Wolfson and his team of prosecutors as they work on an assortment of Sin City crime cases. Production is underway for the six-episode second season. MY Entertainment produces.Meanwhile, Scripps Networks’ HGTV has renewed Vintage Flip for a second season, set to premiere in the summer of 2017. The series stars real estate agent and contractor Jessie Rodriguez and his designer wife Tina and follows them as they search for, purchase and restore vintage homes in Orange County, California. The series is produced by Pie Town Productions.Sister network Cooking Channel brings back its Sugar Showdown for a new season on September 14 at 10 p.m. EST/ 7 p.m. PT. The program, hosted by chef and Epic Meal Time alumnus Josh Elkin features three expert bakers battling it out, crafting sugary treats – pies, cakes and cupcakes galore – in two rounds of challenges. Architect Films produces.Elsewhere, Scripps UK/EMEA has greenlit a second series for Paul Hollywood City Bakes, set for spring of 2017. In season two, the British baker (pictured) will visit such cities as Oslo, Antwerp, Reykjavik, Palermo, Nicosia, Cape Town, Amman, Dublin, Los Angeles and San Francisco, and explore the recipes that have emerged from each in order to craft his own “City Bake” stemming from the experience. Reef Television produces.</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/renewed-and-returning-city-bakes-las-vegas-law', 1471406400, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('review-in-breaking-borders-a-chef-cooks-for-sworn-enemies', 'In ‘Breaking Borders,’ a Chef Cooks for Sworn Enemies', 'review-in-breaking-borders-a-chef-cooks-for-sworn-enemies', 'Take a shopworn, simplistic concept, apply it in an unexpected way, and what do you get? An entertaining and informative travel program.It’s called “Breaking Borders,” and it has its premiere Sunda…', '<p>Take a shopworn, simplistic concept, apply it in an unexpected way, and what do you get? An entertaining and informative travel program.It’s called “Breaking Borders,” and it has its premiere Sunday on the Travel Channel, a blast of substance from an outlet whose shows (“Hotel Impossible,” “Ghost Adventures”) tend toward the frivolous.The journalist Mariana van Zeller and the chef Michael Voltaggio team up to travel to parts of the world where intractable tensions dominate life. They bring together representatives of various sides of a festering conflict, and Mr. Voltaggio serves them a grand dinner featuring local dishes. The hope is that good food shared in a hospitable setting might help enemies find common ground.This is a variation on an old idea that turns up a lot in feel-good documentaries and on the agendas of well-meaning foundations. If only Israeli and Palestinian children could play together in the same orchestra, all the differences would melt away. To apply the formula, substitute other feuding peoples for Israelis and Palestinians, and soccer team or spaceflight or whatever for orchestra.It’s a lovely idea, and it often even makes a difference on a small scale, yet the world’s enmities keep right on boiling. So whether the breaking-bread version in this series actually accomplishes much is open to question. But it makes for a travel/cooking show that’s considerably livelier than most.Ms. van Zeller is engaging and succinct as she summarizes the conflicts in the trouble spot of the week, and Mr. Voltaggio is amusing as he takes a crash course in the local cuisine and visits street markets to buy his ingredients. Their first stop is a gimme: The premiere finds them inviting a Palestinian book store owner, a two-state-solution advocate and several Israeli settlers to dinner in the West Bank.That particular standoff has been so thoroughly scrutinized and has been the subject of so much outside arbitration that you get the sense that the guests are just sort of enacting their assigned roles. Certainly no one at the dinner is learning anything new.But among the fascinating elements of “Breaking Borders” are the differences between the various places Ms. van Zeller and Mr. Voltaggio visit. If the premiere looks in on a well-established and familiar conflict, some subsequent episodes venture into far less certain — and more treacherous — territory.In Egypt, for instance, in the March 29 episode, the pair and their crew are detained several times by the police while getting ready for what they hope will be a dinner that mixes pro-democracy guests with one who supports the current military leadership, and perhaps even a member of the Muslim Brotherhood. In some travel shows, you have a sense that moments of peril — a risky bit of hiking or a nerve-racking encounter with wildlife — are staged or trumped up. Not here.“I swear by God three times, if we see you here again we will arrest you,” a police officer is heard telling their guide after he has apparently bribed his way out of a trip to prison.Much is made of the dinners, but in truth, they tend to be anticlimactic and take up only about a quarter of each hourlong episode. But the tours of the city or country in preparation for the meal are instructive, full of moving interviews with people affected by whatever the local strife is. In places like Egypt, where the political situation is still evolving, the show enhances current headlines. In spots like Sarajevo that haven’t been daily front-page news for a while, it’s a useful reminder of how past trauma resonates in the present.And in all cases, the episodes do what a good travel show is supposed to do: explain and illuminate a part of the world different from our own.Breaking Borders on Travel Channel, Sunday nights at 9, Eastern and Pacific times; 8, Central time.Produced by MY Tupelo Entertainment for Travel Channel. For MY Tupelo Entertainment: Gry Winther, Joe Townley and Michael Yudin, executive producers; Yon Motskin, co-executive producer. For Travel Channel: Brian Leonard, executive producer.</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/review-in-breaking-borders-a-chef-cooks-for-sworn-enemies', 1426219200, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('rtlii-in-germany-to-air-adaptation-of-the-story-labs-hall-pass', 'RTLII in Germany to Air Adaptation of The Story Lab’s Hall Pass', 'rtlii-in-germany-to-air-adaptation-of-the-story-labs-hall-pass', 'A celebrity-focused local version of The Story Lab’s social experiment format Hall Pass will soon premiere on RTLII in Germany.The German series will run under the title 48H Single: Celebrities Tes…', '<p>A celebrity-focused local version of The Story Lab’s social experiment format <em>Hall Pass</em> will soon premiere on RTLII in Germany.The German series will run under the title <em>48H Single: Celebrities Test Their Love</em>. The Story Lab licensed <em>Hall Pass</em> to Joker Productions, which will produce the RTLII version. The German edition will feature celebrity couple Joey and Justine Heindle in the pilot. The first episode will air on October 1 at 11:15 p.m.<em>Hall Pass</em> allows couples who are at a crossroads in their relationship the chance to decide whether they want to remain together or separate after spending a weekend doing whatever they want without suffering any consequences. The format was created by Phileas Productions and MY Entertainment, in collaboration with The Story Lab.Jan von Wussow, the executive director of The Story Lab Germany, said, “We are delighted to offer German couples a ‘Hall Pass’ in <em>48H Single: Celebrities Test Their Love</em>. The unique social experience format is fresh and exciting, inviting couples to test their relationships in unique circumstances, which appeals to the diverse millennial audience. We are thrilled that RTLII have recognized the exciting potential in this format.”Michael Yudin, the founder and president of MY Entertainment, commented, “We are thrilled that RTLII shares our belief in this timely and topical format, and we look forward to working with our partners at Joker Productions and The Story Lab to make it a long-running hit in Germany.”Sergio Sancho, the founder and managing director, Phileas Productions, added, “We are very happy that RTLII is bringing <em>48H Single: Celebrities Test Their Love </em>to German viewers and that Joker is in charge of producing it, which is a guarantee of a great production and content. We believe this is just the first of many more commissions.”</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/rtlii-in-germany-to-air-adaptation-of-the-story-labs-hall-pass', 1537502400, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('series-explores-manson-murders-through-grandsons-eyes', 'Series Explores Manson Murders Through Grandson’s Eyes', 'series-explores-manson-murders-through-grandsons-eyes', 'Zak Bagans has always had a fascination with the darker side of the human psyche.The American television personality is the creator, executive producer, and host of the paranormal series Ghost Adve…', '<p>Zak Bagans has always had a fascination with the darker side of the human psyche.The American television personality is the creator, executive producer, and host of the paranormal series Ghost Adventures (Travel Channel), where Bagans and his team explore the world’s most haunted places. In one of his latest series, Deadly Possessions (Travel Channel), Bagans showcases his collection of haunted artifacts.So it should come as little surprise that when the chance came up for Bagans to explore a new angle of infamous cult leader and convicted mass murderer Charles Manson, it was an opportunity he couldn’t pass up.New York-based independent production company MY Entertainment has announced a high-concept co-production with Zak Bagans Entertainment. The series will follow Jason Freeman, Manson’s grandson, on a quest to meet his 82-year-old grandfather before he dies in prison.The new series will be filmed in several locations, including Freeman’s home in Florida and California, and will feature audio footage between Manson and Freeman, recorded from prison.While Manson’s life has been widely covered in the media, Bagans believes seeing the story told through Freeman’s eyes will offer viewers a perspective they’ve never seen before. What’s more, with both the critical and ratings’ success of docs such as Netflix’s Making a Murderer, ESPN’s OJ: Made in America and ABC’s Truth and Lies: The Menendez Brothers – American Sons, American Murders, consumer appetite for true crime is growing. That’s led Bagans to believe his new project will have no problem finding an audience.“People are drawn to notorious figures,” he tells realscreen. “And Jason’s story is particularly gripping because he’s had to grow up with the stigma attached to the Manson name.”A project of this scale isn’t without its challenges. To go forward with the climactic conclusion of the series — a face-to-face conversation between Freeman and Manson —Bagans has to figure out how to get Freeman and the crew inside the walls of California State Prison-Corcoran where Manson continues to serve a life sentence for a string of high-profile murders, most notably the 1969 stabbing death of actress Sharon Tate.“Getting into the prison has been the hardest thing,” says Bagans. “We have our legal counsel and law enforcement experts, and ultimately were going to make this work. We’re right in the thick of it now, and Jason will be going out to California soon.”The crew has started filming, and they’ll soon be ready to go to market with material to show distributors and commissioners. But Bagans says Freeman has already received a lot of direct interest about the project.“It’s amazing to see how much interest is in Jason already, so I think once we catapult this into actual footage and we get a proof of concept ready, it’ll move very quickly,” Bagan says.</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/series-explores-manson-murders-through-grandsons-eyes', 1486702800, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('sky-vision-gets-my-entertainment-first-look', 'SkyVision Gets MY Entertainment First Look', 'sky-vision-gets-my-entertainment-first-look', 'Sky Vision, the production and distribution arm of UK-based pay TV operator Sky, has secured a first-look distribution deal with US prodco MY Entertainment.As part of the agreement, Sky Vision will…', '<p>Sky Vision, the production and distribution arm of UK-based pay TV operator Sky, has secured a first-look distribution deal with US prodco MY Entertainment.As part of the agreement, Sky Vision will work closely with MY Entertainment as it develops new content and will have access to a selection of programming from its slate with the option to exclusively distribute the projects globally.MY Entertainment is behind shows including Ghost Adventures for Travel Channel, Sin City Justice for Investigation Discovery and UKTV’s Help! My House Is Haunted.Gillian Rose, senior VP of sales and acquisitions at Sky Vision, said MY Entertainment “has tapped into partnerships with several very interesting and innovative producers around the globe, and together we expect to create and distribute some great programming from this alliance.”Michael Yudin, founder and president of MY Entertainment, added: “A key focus of our business strategy is to find creative new ways to retain our IP. What a powerhouse such as Sky Vision does best is to provide unrivalled support for our big-hitting shows, helping to take us to another level while we continue to create, innovate and build relationships around the world in every way we can.”</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/sky-vision-gets-my-entertainment-first-look', 1499832000, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('sky-vision-my-entertainment-ink-exclusive-distro-deal', 'SkyVision & MY Entertainment Ink Distribution Deal', 'sky-vision-my-entertainment-ink-exclusive-distro-deal', 'Sky Vision, the production and distribution arm of Sky, has inked a first-look distribution deal with Sin City Justice producer MY Entertainment.Under the agreement, Sky Vision will have access to …', '<p>Sky Vision, the production and distribution arm of Sky, has inked a first-look distribution deal with Sin City Justice producer MY Entertainment.Under the agreement, Sky Vision will have access to the New York-based indie’s latest development projects with the option to exclusively distribute the new content to the global marketplace.MY Entertainment produces a roster of programs and formats for leading international brands, including Travel Channel’s Ghost Adventures, Investigation Discovery‘s Sin City Justice (pictured) and UKTV’s Help! My House Is Haunted.Most recently, the company teamed with SBS Broadcasting and Critical Density Media on the social experiment format The Power; partnered with former NBA star Tyson Chandler on a forthcoming reality series focused on fashion in sports; and secured a deal to develop content with global health and wellness content company Rodale.</p><p>The deal, meanwhile, will further strengthen Sky Vision’s factual and entertainment portfolio, which currently includes October Films’ Walking the Americas, Whalerock Industries and BattleBots Inc.’s BattleBots and Blast! Films’ Secret Life of the Zoo.“We are delighted to be working with MY Entertainment, a company that has proved itself to be creative and versatile with a strong international entrepreneurial streak,” said Gillian Rose, SVP sales and acquisitions at Sky Vision, in a statement. “MY Entertainment has tapped into partnerships with several very interesting and innovative producers around the globe, and together we expect to create and distribute some great programming from this alliance.”</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/sky-vision-my-entertainment-ink-exclusive-distro-deal', 1499832000, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('story-lab-gets-hall-pass-for-miptv', 'Story Lab gets Hall Pass for MIPTV', 'story-lab-gets-hall-pass-for-miptv', 'London-based investor, producer and distributor The Story Lab has partnered with prodcos in the US and Spain on a new reality format to be launched at MipTV.Hall Pass is the product of a partnershi…', '<p>London-based investor, producer and distributor The Story Lab has partnered with prodcos in the US and Spain on a new reality format to be launched at MipTV.Hall Pass is the product of a partnership between The Story Lab, New York-based factual prodco MY Entertainment and Phileas Productions in Spain.The show is a social experiment that gives couples at a crossroads in their relationship the opportunity to find out if the grass really is greener on the other side by granting each other a 72 hour ‘hall pass’ to do whatever they want with absolutely no consequences.When the couple is reunited they are given the chance to see a video of what their partner did with their free time and must then decide whether they can live up to their ‘no consequences’ part of the bargain and stay together, or go their separate ways.Erik de Winter, head of The Story Lab Netherlands, has brokered a deal for Simpel Media to produce a pilot of the show in the Netherlands, which will be completed in time for MipTV.The Story Lab, known for shopping the Ninja Warrior format in Europe, holds international distribution rights.</p><p>Clive Whittingham</p><p>14-03-2017</p><p>©C21Media</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/story-lab-gets-hall-pass-for-miptv', 1489464000, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('teen-sports-competition-show-mvteen-in-works-at-nbcus-wilshire-studios', 'MYE partners with NBCU’s Wilshire Studios For ‘MVTeen’', 'teen-sports-competition-show-mvteen-in-works-at-nbcus-wilshire-studios', 'Wilshire Studios, the unscripted production arm of NBCUniversal Cable Entertainment, and MY Entertainment are developing MVTeen, a teen sports competition show from the creators of Pros Vs Joes rea…', '<p>Wilshire Studios, the unscripted production arm of NBCUniversal Cable Entertainment, and MY Entertainment are developing MVTeen, a teen sports competition show from the creators of Pros Vs Joes reality series.Hosted by former NFL and NBA stars Jerry Rice and John Salley, MVTeen is described as the ultimate sports competition series for teens featuring some of the most gifted athletes in the country.In the potential series, all-star professional athletes will join hosts Rice and Salley to coach two teams of four student athletes (two female and two male) who will face off each week and go head-to-head in an all-around classic sports competition. They’ll compete in basketball, soccer, football, softball, the classic rope climb, 50-yard dash, among other things. The show will test every aspect of a true teenage champion, while sharing their personal stories of triumph. At the end of each episode, the top teen female and male athlete will advance to the finals for a chance to compete for the overall title of “Top Athlete of the Year” and a cash prize towards college.Pros vs Joes reality game show aired on Spike from 2006-1010 and featured amateur male contestants (the Joes) against professional athletes (the Pros).MVTeen is a co-production with Wilshire Studios and MY Entertainment. Joe Townley and Michael Yudin serve as executive producers for MY Entertainment. Rice and Salley are co-executive producers.</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/teen-sports-competition-show-mvteen-in-works-at-nbcus-wilshire-studios', 1517547600, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('the-story-lab-partners-for-hall-pass-format', 'The StoryLab Partners for Hall Pass Pilot', 'the-story-lab-partners-for-hall-pass-format', 'LONDON: The Story Lab has aligned with MY Entertainment in the U.S. and Phileas Productions in Spain to produce a pilot for the reality format Hall Pass.', '<p>LONDON: The Story Lab has aligned with MY Entertainment in the U.S. and Phileas Productions in Spain to produce a pilot for the reality format Hall Pass.</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/the-story-lab-partners-for-hall-pass-format', 1489464000, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('travel-channel-breaks-records-with-ghost-adventures-live', 'Travel Channel Breaks Records with ''Ghost Adventures Live''', 'travel-channel-breaks-records-with-ghost-adventures-live', 'Travel Channel earned its best prime rating (L+3) In network history for the Ghost Adventures Live event on Halloween night among P25-54 and W25-54. Averaging more than 1.1 million Total Viewers (P…', '<p><strong>Travel Channel</strong> earned its best prime rating (L+3) In network history for the <strong>Ghost Adventures Live</strong> event on Halloween night among P25-54 and W25-54. Averaging more than 1.1 million Total Viewers (P2+), the special ranked #3 in ad-supported cable for delivery of W25-54, #4 for P25-54 and #10 for P2+.</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/travel-channel-breaks-records-with-ghost-adventures-live', 1541739600, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('travel-channel-orders-deadly-possessions-from-my-entertainment-and-ghost-adventures-creator-and-star-zak-bagans', 'Travel Channel Orders Deadly Possessions', 'travel-channel-orders-deadly-possessions-from-my-entertainment-and-ghost-adventures-creator-and-star-zak-bagans', 'MY ENTERTAINMENT, has announced today its latest commission Deadly Possessionsfrom the Travel Channel, a new 6 x 60’ series premiering at 9pm on April 2nd starring Zak Bagans, creator, executive pr…', '<p>MY ENTERTAINMENT, has announced today its latest commission Deadly Possessionsfrom the Travel Channel, a new 6 x 60’ series premiering at 9pm on April 2nd starring Zak Bagans, creator, executive producer and host of Travel Channel’s hit paranormal series Ghost Adventures.Bagans will share his collection of haunted items and their chilling stories through fulfilling a lifelong dream of opening a museum in downtown Las Vegas, full of the haunted and cursed objects he has been collecting through the years.Each episode of Deadly Possessions features three items and their owners. They share stories of how these objects have allegedly terrorized them and others whilst Bagans interviews the owners and works with them to get to the root of their attachment to the object so they can free themselves or at least escape harm from these “deadly possessions.” Items featured in the series include the Dibbuk box, the inspiration for the 2012 Sam Raimi produced film The Possession, Robert, the killer doll that inspired the Chucky films and a secret possession implicated in the death of actress Natalie Wood.Michael Yudin said: As we are currently in production of our 11th season of Ghost Adventures, it’s great to see this latest project from Zak come to fruition and the massive response he’s had setting up his museum and the search for objects that hold some of the fascinating stories imaginable. All of the MY Entertainment team is fired up for yet another successful collaboration with Zak.’Zak Bagans said, ‘I’m excited to share my passion even further for all things mysterious with Deadly Possessions. The doors will now be open to my Haunted Museum welcoming the most possessed objects in the world and the people whose lives who have been affected and even lost by them.”<strong>About MY Entertainment</strong>:MY Entertainment is a successful independent production company launched in 2000 by veteran TV producer and advertising executive, Michael Yudin. &nbsp;In addition to creating and producing compelling content, MY Entertainment has become known for pioneering new business models with advertisers, broadcasters and production companies in the US and around the world. MY Entertainment’s current series include; the 12th season of Ghost Adventures, for Travel Channel, Las Vegas Law for Investigation Discovery, Baggage Battles for Scripps International Networks, Paranormal Museum and You Only Live Once for Travel Channel and Sherman’s Warriors for NBC Sports Digital platform. With offices in NY and LA, the company currently has projects in development with Discovery, History, Travel, Lifetime, WE tv, Travel and Discovery Science. MY Entertainment is perhaps best known for the long running hit series, Pros vs. Joes.<strong>About Zak Bagans:</strong>Zak Bagans is best known as the host, creator and executive producer of number 1-rated Travel Channel TV series Ghost Adventures, which launched in 2008. In 2011, Bagans hosted and produced Travel Channel’s Paranormal Challenge. In the same year, he also narrated the Travel Channel special, Ultimate Travel: Legends of the Parks, about paranormal activity in US national parks. He has created and produced other shows for the Travel Channel as well “Paranormal Paparazzi”, “Netherworld” and “Aftershocks”. &nbsp;Zak is also an acclaimed NY-Times Bestselling author for Dark World: Into the Shadows with the Lead Investigator of the Ghost Adventures Crew. &nbsp; In 2012, Bagans produced a music album with Praga Khan of Lords of Acid &nbsp;the full-length album entitled NecroFusion, topped the Electronic album charts on iTunes hitting #1. Bagans’ recent projects include executive producing the feature film Sympathy, Said the Shark, which won the Audience Award from the Portland Film Festival in 2016 and is also directing, executive producing and starring in a feature film documentary, The Demon House, releasing in 2016.<strong>‍</strong></p><p><strong>For further information on MY Entertainment, please contact:</strong></p><p><strong>‍</strong>Cheryl Clarke at Mushroom Media on:</p><p>Tel: +44 (0)7939554109</p><p>E: cheryl@mushroom-media.co.uk</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/travel-channel-orders-deadly-possessions-from-my-entertainment-and-ghost-adventures-creator-and-star-zak-bagans', 1459310400, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('travel-channel-orders-digital-series-ten-best-places', 'Travel Channel Orders Digital Series “Ten Best Places”', 'travel-channel-orders-digital-series-ten-best-places', 'Scripps Networks Interactive-owned Travel Channel has commissioned an online travel series from MY Digital.The New York-based company, which is owned by MY Entertainment, is producing the web serie…', '<p>Scripps Networks Interactive-owned Travel Channel has commissioned an online travel series from MY Digital.The New York-based company, which is owned by MY Entertainment, is producing the web series Ten Best Places with… (pictured) for Travel Channel Originals. The 10-part series focuses on the most Googled destinations and travel topics.Scripps-owned online lifestyle network Ulive has also renewed the MY Digital-produced Trip Smart for a second season. Hosted by travel reporter Peter Greenberg, the series gives viewers tips on how to travel cheaper and hassle free.The commissions follow the debut of a MY Digital-produced web series about former Green Bay Packers head coach Mike Sherman for NBC Sports Digital. Sherman’s Warriors (6 x 10 minutes) follows Sherman as he coaches a high-school football team in Cape Cod. The series is the first to fall under NBC’s digital strand of short-form sports programming airing across NBC’s various platforms.</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/travel-channel-orders-digital-series-ten-best-places', 1446264000, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('uktv-buys-my-entertainment-paranormal-series', 'UKTV Buys MY Entertainment Paranormal Series', 'uktv-buys-my-entertainment-paranormal-series', 'Michael Yudin''s New York-based factual production company MY Entertainment has sold an original, 12-part paranormal series Help! My House Is Haunted to UKTV. Now in its thirteenth season, the 12x60…', '<p>Michael Yudin''s New York-based factual production company MY Entertainment has sold an original, 12-part paranormal series Help! My House Is Haunted to UKTV.</p><p>Now in its thirteenth season, the 12x60’ series features an expert team of international investigators, Chris Fleming, Sandy Landar and Barri Ghai, who will look into local incidences of paranormal activity reported by owners of homes who believe them to be haunted. Families present a case file to the experts who then research historical evidence. The series will air early in 2018 on Really, home to Ghost Adventures in the UK and paranormal event #Frightday.Help! My House Is Haunted! is a co-production with UK indie Back2Back Productions and the executive producers are Zak Bagans, David Notman-Watt for Back2Back and Michael Yudin for MY Entertainment, with international distribution rights awarded to Alfred Haber Television. It was created by Zak Bagans, the creator, executive producer and host of Travel Channel''s hit US series Ghost Adventures.“Our viewers love Zak so we''re thrilled to have another Zak Bagans show exclusive to Really,” said Emma Sparks, acquisitions and co-production manager, UKTV. “I am delighted to be working with Michael, Zak and David on this brand new series. <a href="https://myentertainment.tv/">My Entertainment</a> are leaders in the paranormal genre so we know we''ll have a hit series and it''s great that the team will be coming over to the UK to investigate the paranormal activity in our family homes.”Yudin added: “We launched two development initiatives over the past few years: a global strategy to co-develop and sell programming not just in the US, but around the world – and a partnership with the incredibly talented and prolific Zak Bagans. I''m delighted to see both strategies come together and prove successful with the announcement of this series commission for <a href="https://www.rapidtvnews.com/corporate.uktv.co.uk">UKTV</a>. But it always takes a willing partner, and that in we have in Emma Sparks. The truth is, this would have never happened without Emma''s foresight and determination.”</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/uktv-buys-my-entertainment-paranormal-series', 1490155200, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('uktv-increases-paranormal-activity', 'UKTV Increases Paranormal Activity', 'uktv-increases-paranormal-activity', 'UKTV is to coproduce a 12-part paranormal series with the creators of long-running Travel Channel show Ghost Adventures. Help! My House is Haunted! (12×60’) has been created by Zak Bagans, the exec…', '<p>UKTV is to coproduce a 12-part paranormal series with the creators of long-running Travel Channel show Ghost Adventures. Help! My House is Haunted! (12×60’) has been created by Zak Bagans, the executive producer and host of Ghost Adventures, which is now in its 13th season.UKTV will air the show on its Really channel, the UK home of Ghost Adventures, early in 2018.The series is being coproduced by Michael Yudin’s New York-based factual prodco MY Entertainment and UK firm Back2Back with UKTV. Alfred Haber Television holds international distribution rights.Help! My House is Haunted! was ordered by UKTV acquisitions and coproduction manager Emma Sparks and Really general manager Luke Hales.Bagans and Yudin will executive produce alongside David Notman-Watt for Brighton-based indie Back2Back.The show follows a team of investigators who look into homeowners’ reports of paranormal activity.MY Entertainment has entered into an exclusive development deal with Bagans that has seen this commission – plus a coproduction with access to Charles Manson’s grandson Jason Freeman, who wants to meet his notorious murderer grandfather before he dies in prison – added its slate.</p><p><a href="https://www.c21media.net/author/clivewhittingham/">Clive Whittingham</a>21-03-2017 © C21Media</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/uktv-increases-paranormal-activity', 1490068800, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('uktv-to-coproduce-series-with-us-producer', 'UKTV to Coproduce Series with US Producer MY Entertainment', 'uktv-to-coproduce-series-with-us-producer', 'British multichannel operator UKTV has acquired and will coproduce a twelve-part paranormal-themed series from New York-based producer MY Entertainment.Help! My House is Haunted comes from Zak Baga…', '<p>British multichannel operator UKTV has acquired and will coproduce a twelve-part paranormal-themed series from New York-based producer MY Entertainment.Help! My House is Haunted comes from Zak Bagans, who is creator and host of long-running Travel Channel series Ghost Adventures. UK-based Back2Back Productions is a coproducer.Bagans and David Notman-Watt are executive producer for Back2Back and Michael Yudin (pictured) does the same for MY, with international distribution rights awarded to Alfred Haber Television.UKTV, owned by BBC Worldwide and Scripps Networks International, ordered game show Go 8-Bit from another New York-based producer, DLT Entertainment last year.UKTV will play Help! on pay TV channel Really early next year. It will follow an expert team of international investigators, who look into incidences of paranormal activity based on case files families present to them.Emma Sparks, UKTV’s acquisitions and coproduction manager, and Really general manager Luke Hales ordered the show.For MY, the deal comes as part of a concerted push into international production and format development, and following an exclusive development and production deal with Bagans. “We launched two development initiatives over the past few years: a global strategy to co-develop and sell programming not just in the US, but around the world – and a partnership with the incredibly talented and prolific Zak Bagans,” said Yudin.“Our viewers love Zak so we’re thrilled to have another ‘Zak Bagans’ show exclusive to Really,” said Sparks. “I am delighted to be working with Michael, Zak and David on this brand new series, [and] MY Entertainment are leaders in the paranormal genre so we know we’ll have a hit series and it’s great that the team will be coming over to the UK to investigate the paranormal activity in our family homes.”</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/uktv-to-coproduce-series-with-us-producer', 1490068800, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('uktv-turns-to-us-indie-to-hunt-ghosts', 'UKTV Turns to US Indie MY Entertainment to Hunt Ghosts', 'uktv-turns-to-us-indie-to-hunt-ghosts', 'UKTV’s Really has acquired a 12-part paranormal series from US indie My Entertainment. The pay-TV broadcaster has picked up Help! My House Is Haunted, a format created by the host of US show Ghost …', '<p>UKTV’s Really has acquired a 12-part paranormal series from US indie My Entertainment. The pay-TV broadcaster has picked up Help! My House Is Haunted, a format created by the host of US show Ghost Adventures, Zak Bagans which also airs on Really.It is UKTV’s latest paranormal order following last year’s stripped event Celebrity Haunted Hotel Live, produced by North One Television.New York-based indie My Entertainment, set up by former NBC exec Michael Yudin, has partnered with Brighton-based producer Back2Back to produce the 12 x 60-minute series.The show features investigators Chris Fleming, Sandy Landar and Barri Ghai, who look into incidences of paranormal activity reported by home owners. In each episode, families present a case file to the experts who then research historical evidence of hauntings.Help! My House Is Haunted was bought by Really general manager Luke Hales and Emma Sparks, UKTV’s acquisitions and co-production manager. It will be exec produced Yudin, Bagans and Back2Back’s David Notman-Watt. Sparks said: “Our viewers love Zak so we’re thrilled to have another Zak Bagans show exclusive to Really.“My Entertainment are leaders in the paranormal genre so we know we’ll have a hit series and it’s great that the team will be coming over to the UK to investigate the paranormal activity in our family homes.”</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/uktv-turns-to-us-indie-to-hunt-ghosts', 1489723200, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('viaplay-preps-original-manson-doc', 'Viaplay preps original Manson doc', 'viaplay-preps-original-manson-doc', 'Nordic Entertainment Group (NENT) has commissioned a four-part documentary series about American cult leader and murderer Charles Manson for its Viaplay streaming service.Manson’s Bloodline is the …', '<p>Nordic Entertainment Group (NENT) has commissioned a four-part documentary series about American cult leader and murderer Charles Manson for its Viaplay streaming service.Manson’s Bloodline is the latest original factual series to premiere on Viaplay and is due to debut on August 9. It is part of a drive to premiere 20 original series on the service every year.The series will feature, for the first time, Manson’s only living relative, his grandson Jason Freeman, telling his unsettling story.Manson’s Bloodline follows Freeman for 16 months as he struggles with the legacy left by one of the most notorious criminals in American history.The doc, which is produced by New York-based MY Entertainment, will be distributed globally by NENT-owned UK broadcaster DRG.NENT recently commissioned two seasons of documentary series American Runestone by Swedish Hollywood star Peter Stormare, joining previous original docs Swedish Sin, Four Hands Menu, Couple Thinkers and Superswede on its slate.</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/viaplay-preps-original-manson-doc', 1563422400, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER),
  ('we-tried-it-i-went-hunting-for-ghosts-with-travel-channels-ghost-adventures', 'We Tried It: I Went Hunting For Ghosts with Travel Channel’s Ghost Adventures!', 'we-tried-it-i-went-hunting-for-ghosts-with-travel-channels-ghost-adventures', 'I like to think of myself as a skeptical believer.But when Travel Channel debuted their highest-rated series Ghost Adventures in October 2008, I was hooked. For more than 200 episodes, founder Zak …', '<p>I like to think of myself as a skeptical believer.But when Travel Channel debuted their highest-rated series <a target="_blank" href="https://www.travelchannel.com/shows/ghost-adventures"><em>Ghost Adventures</em></a> in October 2008, I was hooked. For more than 200 episodes, founder Zak Bagans has led his team of Aaron Goodwin, Billy Tolley and Jay Wasley as they investigate some of the most haunted locations around the country and abroad.Over the last decade, they’ve captured disembodied voices, apparitions, objects moving on their own, not to mention being touched, scratched and pushed by unseen forces. And I’ve loved watching every minute of it (although admittedly it was almost always from under a blanket with all the lights on).So when the guys gave me the chance to get off my couch and experience what it’s really like to go on an investigation, I was cautiously game. I naively assumed it couldn’t possibly be as scary as it seems on TV.At the end of August, I met up with the team in Eureka, Utah, an old mining town just south of Salt Lake City. I sat and talked with all four of them before the lock-down began and they each explained why they got into this field. “I love being out here and being a detective with these guys,” Zak said. “Our experiences fuel us. It’s a rush.” All of them nodded in agreement. “It’s a passion and I love to explore the unknown,” said Jay. “It opens a door,” Billy added, “to say if that’s possible, are all these other things possible?”We were positioned outside on the small town’s Main Street and the buildings we would be investigating each had their own history. One was a former saloon and billiards hall, the other a bank with an old holding cell still in the basement. Zak asked if I was ready. Aaron jumped up and down in excitement for “the hunt.” And despite my trepidation, their energy was contagious.I took a deep breath and followed Zak into the building. It looks dark on TV but let me tell you, it is truly impossible to see. Even when your eyes adjust, which Zak assured me would happen, you still have to feel your way around and watch your footing in the blackness.As we were standing there, I sensed a breeze move from my left to my right. It felt exactly like it would if you were next to an air vent when it turned on. Only there was no vent. Jay then said he saw a light anomaly pass right by me.Zak also captured several EVPs (Electronic Voice Phenomenon), which are what sound like disembodied voices and whispers on a digital recording when no one is talking. And I knew he was going to suggest leaving me alone somewhere (I <em>knew</em> it!). Part of the joy of the show is watching Zak lock Aaron away someplace dark to investigate. “I understand why and I’m down for it,” Aaron told me. “But it’s still scary to be all by yourself.” When they left me alone in the basement by the old cell, I was nothing short of terrified.I enjoy yoga but deep breaths can only do so much to calm your nerves. When you see a ball of light go across a wall in front of you and you know without a doubt that there is no external source, it can be extremely disconcerting. But I made it (without hyperventilating—too much).Truth be told, I opted out of the last part of the investigation. Okay, I chickened out. Hearing that someone is going to “do a ritual” to “open a portal” at a house at first sounds intriguing. But then I started fixating on the end of <em>Raiders of the Lost Ark</em>. You know, where they open the Ark of the Covenant and all these spirits come out and you think they’re beautiful but oh no, they melt your face off? Yeah, I kept hearing Harrison Ford tell Karen Allen, “Marion, don’t look at it. Shut your eyes, Marion, and don’t look at it no matter what happens.”And yes, I am well aware it was just a movie. But it still scarred me enough as a 10-year-old to make me realize that it couldn’t hurt to just wait outside in the car and let the guys report back, thank you very much.So what happened? You can watch for yourself when the episode airs on Nov. 24 at 9 p.m. ET. I’ll just say that Zak found me afterwards and played the audio evidence they had just captured on their digital recorder. I wouldn’t even want to try and describe what it sounded like or might be. All I can say is that I instinctively put my hands over my ears because it honestly felt like something I should not be hearing. It was absolutely horrifying.But that is the beauty of this show—Zak, Aaron, Billy and Jay constantly put themselves out there to tackle the unknown so that viewers don’t actually have to. Even they get scared at times but as Zak told me, “That’s why it’s called an adventure.” As always, they leave it to us to be the judge.All I know is that I still can’t get what I heard out of my head. It shook me to my core. Because ultimately it doesn’t matter whether you’re a skeptic or a believer, if you like facing your fears, then you will love <em>Ghost Adventures</em>.<em>Ghost Adventures</em> airs on Saturdays at 9 p.m. ET/PT on Travel Channel.</p><p>‍<em>Ghost Adventures Live</em>, a four-Hour live Halloween investigation, airs Oct. 31 beginning at 8 p.m. ET/5 p.m. PT.</p>', 'myentertainment.tv', 'https://www.myentertainment.tv/press-releases/we-tried-it-i-went-hunting-for-ghosts-with-travel-channels-ghost-adventures', 1539921600, 0, EXTRACT(EPOCH FROM NOW())::INTEGER, EXTRACT(EPOCH FROM NOW())::INTEGER);
